def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        if not isinstance(text, str):
            return None
        text = text.strip()
        parts = text.split(":")
        if len(parts) != 2:
            return None
        if parts[0] == "" or parts[1] == "":
            return None
        if not parts[0].isdigit() or not parts[1].isdigit():
            return None
        hour = int(parts[0])
        minute = int(parts[1])
        if minute < 0 or minute >= 60:
            return None
        if hour < 0 or hour > 24:
            return None
        if hour == 24 and minute != 0:
            return None
        return hour * 60 + minute

    def format_time(total):
        hour = total // 60
        minute = total % 60
        h = str(hour)
        m = str(minute)
        if len(h) == 1:
            h = "0" + h
        if len(m) == 1:
            m = "0" + m
        return h + ":" + m

    def quarter_up(value):
        return ((value + 14) // 15) * 15

    def find_times_in_text(text):
        found = []
        if not isinstance(text, str):
            return found
        i = 0
        n = len(text)
        while i + 4 < n:
            piece = text[i:i + 5]
            t = parse_time(piece)
            if t is not None:
                found.append(t)
                i += 5
            else:
                i += 1
        return found

    def get_interval(item):
        start = None
        end = None
        if isinstance(item, dict):
            pairs = [
                ("start", "end"),
                ("start_time", "end_time"),
                ("from", "to"),
                ("begin", "finish"),
                ("begin", "end"),
                ("start", "finish"),
                ("time_start", "time_end")
            ]
            for a, b in pairs:
                if a in item and b in item:
                    start = parse_time(item[a])
                    end = parse_time(item[b])
                    if start is not None and end is not None:
                        return [start, end]
            if "start" in item:
                start = parse_time(item["start"])
            if "end" in item:
                end = parse_time(item["end"])
            if start is not None and end is not None:
                return [start, end]
            return None
        if isinstance(item, list) or isinstance(item, tuple):
            if len(item) >= 2:
                start = parse_time(item[0])
                end = parse_time(item[1])
                if start is not None and end is not None:
                    return [start, end]
            return None
        if isinstance(item, str):
            times = find_times_in_text(item)
            if len(times) >= 2:
                return [times[0], times[1]]
        return None

    def extract_events(raw):
        if raw is None:
            return []
        if isinstance(raw, dict):
            for key in ["events", "busy", "calendar", "items"]:
                if key in raw and isinstance(raw[key], list):
                    raw = raw[key]
                    break
            else:
                raw = list(raw.values())
        if not isinstance(raw, list):
            raw = [raw]
        return raw

    def free_for_slot(merged, start, end):
        for busy_start, busy_end in merged:
            if busy_start >= end:
                break
            if busy_end > start and busy_start < end:
                return False
        return True

    earliest_min = parse_time(earliest) if earliest else 0
    if earliest_min is None:
        earliest_min = 0
    latest_min = parse_time(latest_end) if latest_end else 24 * 60
    if latest_min is None:
        latest_min = 24 * 60

    result = {}

    for day in days:
        busy = []
        people = [""] + attendees
        for person in people:
            raw = api.read_calendar(person, day)
            events = extract_events(raw)
            for event in events:
                interval = get_interval(event)
                if interval is None:
                    continue
                start = interval[0]
                end = interval[1]
                if end <= start:
                    continue
                if start < 0:
                    start = 0
                if end > 24 * 60:
                    end = 24 * 60
                if start < end:
                    busy.append([start, end])

        if busy:
            busy.sort()
            merged = [busy[0]]
            for start, end in busy[1:]:
                if start <= merged[-1][1]:
                    if end > merged[-1][1]:
                        merged[-1][1] = end
                else:
                    merged.append([start, end])
        else:
            merged = []

        first_start = quarter_up(earliest_min)
        last_start = ((latest_min - minutes) // 15) * 15

        starts = []
        if minutes > 0 and last_start >= first_start:
            candidate = first_start
            while candidate <= last_start and candidate < 24 * 60:
                if free_for_slot(merged, candidate, candidate + minutes):
                    starts.append(format_time(candidate))
                candidate += 15

        if starts:
            result[day] = starts

    return {"starts": result}
