def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

    def round_up_quarter(total):
        remainder = total % 15
        if remainder == 0:
            return total
        return total + (15 - remainder)

    def parse_hours(text):
        parts = text.split("-")
        return to_minutes(parts[0]), to_minutes(parts[1])

    def merge_busy(events, start_limit, end_limit):
        items = []
        for event in events:
            if event.get("show_as", "busy") != "free":
                start = to_minutes(event["start"])
                end = to_minutes(event["end"])
                if end > start_limit and start < end_limit:
                    if start < start_limit:
                        start = start_limit
                    if end > end_limit:
                        end = end_limit
                    if start < end:
                        items.append([start, end])
        items.sort()
        merged = []
        for start, end in items:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                if end > merged[-1][1]:
                    merged[-1][1] = end
        return merged

    people = []
    seen = {}
    for person in [""] + attendees:
        if person not in seen:
            seen[person] = 1
            people.append(person)

    calendars = {}
    for person in people:
        calendars[person] = api.read_calendar(person, "")

    global_start = 0
    global_end = 24 * 60

    for person in people:
        cal = calendars[person]
        work_start, work_end = parse_hours(cal.get("working_hours", "00:00-23:59"))
        if earliest:
            e = to_minutes(earliest)
            if e > work_start:
                work_start = e
        if latest_end:
            l = to_minutes(latest_end)
            if l < work_end:
                work_end = l
        if work_start > global_start:
            global_start = work_start
        if work_end < global_end:
            global_end = work_end

    result = {"starts": {}}
    if global_end - global_start < minutes:
        return result

    first_start = round_up_quarter(global_start)
    last_start = global_end - minutes

    for day in days:
        busy_by_person = []
        for person in people:
            cal = calendars[person]
            work_start, work_end = parse_hours(cal.get("working_hours", "00:00-23:59"))
            if earliest:
                e = to_minutes(earliest)
                if e > work_start:
                    work_start = e
            if latest_end:
                l = to_minutes(latest_end)
                if l < work_end:
                    work_end = l

            day_events = []
            for entry in cal.get("days", []):
                if entry.get("day") == day:
                    day_events = entry.get("events", [])
                    break

            busy_by_person.append(merge_busy(day_events, work_start, work_end))

        starts = []
        start_time = first_start
        while start_time <= last_start:
            end_time = start_time + minutes
            ok = True
            for person_busy in busy_by_person:
                for busy_start, busy_end in person_busy:
                    if start_time < busy_end and end_time > busy_start:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                starts.append(to_time(start_time))
            start_time += 15

        if starts:
            result["starts"][day] = starts

    return result
