def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def day_to_api(day):
        d = day.strip().lower()
        m = {
            "mon": "Monday", "monday": "Monday",
            "tue": "Tuesday", "tues": "Tuesday", "tuesday": "Tuesday",
            "wed": "Wednesday", "weds": "Wednesday", "wednesday": "Wednesday",
            "thu": "Thursday", "thur": "Thursday", "thurs": "Thursday", "thursday": "Thursday",
            "fri": "Friday", "friday": "Friday",
        }
        if d in m:
            return m[d]
        return day

    def parse_time(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def parse_offset(text):
        sign = -1 if text[0] == "-" else 1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def round_up_quarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def merge_ranges(ranges):
        if not ranges:
            return []
        ranges.sort()
        merged = [ranges[0][:]]
        i = 1
        while i < len(ranges):
            start = ranges[i][0]
            end = ranges[i][1]
            if start > merged[-1][1]:
                merged.append([start, end])
            elif end > merged[-1][1]:
                merged[-1][1] = end
            i += 1
        return merged

    result = {"starts": {}}
    if not days:
        return result

    earliest_min = parse_time(earliest) if earliest else 0
    latest_min = parse_time(latest_end) if latest_end else 1440

    i = 0
    while i < len(days):
        day_input = days[i]
        day_api = day_to_api(day_input)

        user_calendar = api.read_calendar("", day_api)
        if "days" not in user_calendar or not user_calendar["days"]:
            i += 1
            continue

        user_offset = parse_offset(user_calendar["utc_offset"])
        day_key = user_calendar["days"][0]["day"]

        all_busy = []
        allowed_start = 0
        allowed_end = 1440

        people = [("",
                   user_calendar)] + [(name, api.read_calendar(name, day_api)) for name in attendees]

        j = 0
        while j < len(people):
            person_name = people[j][0]
            calendar = people[j][1]

            person_offset = parse_offset(calendar["utc_offset"])
            shift = user_offset - person_offset

            buffer = 0
            note = calendar.get("note", "")
            note_text = note.lower()
            if "15 minutes free before and after" in note_text:
                buffer = 15

            wh = calendar.get("working_hours", "00:00-23:59")
            wh_start = parse_time(wh[0:5]) + shift + buffer
            wh_end = parse_time(wh[6:11]) + shift - buffer

            if wh_start < 0:
                wh_start = 0
            if wh_end > 1440:
                wh_end = 1440

            if wh_start > allowed_start:
                allowed_start = wh_start
            if wh_end < allowed_end:
                allowed_end = wh_end

            day_list = calendar.get("days", [])
            if day_list:
                events = day_list[0].get("events", [])
                k = 0
                while k < len(events):
                    event = events[k]
                    if event.get("show_as", "busy") != "free":
                        start = parse_time(event["start"]) + shift - buffer
                        end = parse_time(event["end"]) + shift + buffer
                        if end > 0 and start < 1440 and start < end:
                            if start < 0:
                                start = 0
                            if end > 1440:
                                end = 1440
                            if start < end:
                                all_busy.append([start, end])
                    k += 1

            j += 1

        if latest_end:
            if latest_min < allowed_end:
                allowed_end = latest_min

        if earliest_min > allowed_start:
            allowed_start = earliest_min

        allowed_start = round_up_quarter(allowed_start)
        latest_start = allowed_end - minutes

        if allowed_start <= latest_start:
            merged_busy = merge_ranges(all_busy)
            starts = []
            current = allowed_start
            while current <= latest_start:
                end_time = current + minutes
                ok = True
                m = 0
                while m < len(merged_busy):
                    bstart = merged_busy[m][0]
                    bend = merged_busy[m][1]
                    if end_time <= bstart:
                        break
                    if current < bend and end_time > bstart:
                        ok = False
                        break
                    m += 1
                if ok:
                    hh = current // 60
                    mm = current % 60
                    starts.append(("0" + str(hh))[-2:] + ":" + ("0" + str(mm))[-2:])
                current += 15

            if starts:
                result["starts"][day_key] = starts

        i += 1

    return result
