def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def to_time(total):
        return str(total // 60).rjust(2, "0") + ":" + str(total % 60).rjust(2, "0")

    def next_quarter(total):
        remainder = total % 15
        if remainder == 0:
            return total
        return total + (15 - remainder)

    if len(days) == 0:
        return {"starts": {}}

    people = [""]
    for person in attendees:
        if person not in people:
            people.append(person)

    calendars = {}
    work_hours = {}
    for person in people:
        calendars[person] = {}
        work_hours[person] = ""
        for day in days:
            data = api.read_calendar(person, day)
            if work_hours[person] == "" and "working_hours" in data:
                work_hours[person] = data["working_hours"]

            day_info = None
            if "days" in data:
                for item in data["days"]:
                    if item.get("day") == day:
                        day_info = item
                        break
            elif data.get("day") == day:
                day_info = data
            elif "events" in data:
                day_info = data

            calendars[person][day] = day_info
            if work_hours[person] == "" and day_info is not None and "working_hours" in day_info:
                work_hours[person] = day_info["working_hours"]

    result = {}
    for day in days:
        day_start = 0
        day_end = 24 * 60

        if earliest != "":
            day_start = to_minutes(earliest)
        if latest_end != "":
            day_end = to_minutes(latest_end)

        for person in people:
            info = calendars[person].get(day)
            wh = work_hours[person]
            if info is not None and "working_hours" in info and info["working_hours"] != "":
                wh = info["working_hours"]

            if wh != "":
                parts = wh.split("-")
                if len(parts) == 2:
                    ws = to_minutes(parts[0])
                    we = to_minutes(parts[1])
                    if ws > day_start:
                        day_start = ws
                    if we < day_end:
                        day_end = we

        if day_start + minutes > day_end:
            continue

        first_start = next_quarter(day_start)
        last_start = day_end - minutes
        if first_start > last_start:
            continue

        starts = []
        candidate = first_start
        while candidate <= last_start:
            candidate_end = candidate + minutes
            free = True

            for person in people:
                info = calendars[person].get(day)
                events = []
                if info is not None and "events" in info:
                    events = info["events"]

                for event in events:
                    if event.get("show_as") == "free":
                        continue
                    event_start = to_minutes(event["start"])
                    event_end = to_minutes(event["end"])
                    if candidate < event_end and candidate_end > event_start:
                        free = False
                        break

                if not free:
                    break

            if free:
                starts.append(to_time(candidate))

            candidate += 15

        if len(starts) > 0:
            result[day] = starts

    return {"starts": result}
