def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parseTime(text):
        return int(text[:2]) * 60 + int(text[3:5])

    def formatTime(value):
        return "%02d:%02d" % (value // 60, value % 60)

    def parseOffset(text):
        sign = 1
        if text and text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def convertTime(value, userOffset, personOffset):
        return value + (userOffset - personOffset)

    def getEntry(response, target):
        items = response.get("days", [])
        if not items:
            return {"day": target[:3].lower(), "events": []}
        wanted = target[:3].lower()
        lowerTarget = target.lower()
        for item in items:
            dayName = item.get("day", "").lower()
            if dayName == wanted or dayName == lowerTarget:
                return item
        return items[0]

    startsByDay = {}

    for day in days:
        userResponse = api.read_calendar("", day)
        userOffset = parseOffset(userResponse.get("utc_offset", "+00:00"))
        userEntry = getEntry(userResponse, day)

        personData = [("", userResponse)]
        for person in attendees:
            if person != "":
                personData.append((person, api.read_calendar(person, day)))

        workBounds = []
        busyBounds = []

        for person, response in personData:
            personOffset = parseOffset(response.get("utc_offset", "+00:00"))
            workText = response.get("working_hours", "00:00-00:00")
            workStart = convertTime(parseTime(workText[:5]), userOffset, personOffset)
            workEnd = convertTime(parseTime(workText[6:]), userOffset, personOffset)
            workBounds.append((workStart, workEnd))

            entry = getEntry(response, day)
            busy = []
            for event in entry.get("events", []):
                if event.get("show_as") == "free":
                    continue
                start = convertTime(parseTime(event["start"]), userOffset, personOffset)
                end = convertTime(parseTime(event["end"]), userOffset, personOffset)
                busy.append((start, end))
            busyBounds.append(busy)

        scanStart = 0
        if earliest:
            scanStart = parseTime(earliest)
        remainder = scanStart % 15
        if remainder:
            scanStart += 15 - remainder

        scanEnd = 24 * 60 - minutes
        if latest_end:
            scanEnd = parseTime(latest_end) - minutes

        dayStarts = []
        if scanEnd >= scanStart:
            start = scanStart
            while start <= scanEnd:
                end = start + minutes
                good = True

                for index in range(len(personData)):
                    workStart, workEnd = workBounds[index]
                    if start < workStart or end > workEnd:
                        good = False
                        break
                    for busyStart, busyEnd in busyBounds[index]:
                        if start < busyEnd and end > busyStart:
                            good = False
                            break
                    if not good:
                        break

                if good:
                    dayStarts.append(formatTime(start))
                start += 15

        if dayStarts:
            startsByDay[userEntry.get("day", day[:3].lower())] = dayStarts

    return {"starts": startsByDay}
