def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def parse_hours(text):
        parts = text.split("-")
        return to_minutes(parts[0]), to_minutes(parts[1])

    def clip_interval(start, end, intervals):
        if end < start:
            end = end + 1440
        if end <= 0 or start >= 1440:
            return
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if start < end:
            intervals.append((start, end))

    def day_entry(info):
        days_list = info.get("days", [])
        if days_list:
            return days_list[0]
        return {}

    result = {}
    if not days:
        return {"starts": result}

    earliest_min = 0
    if earliest:
        earliest_min = to_minutes(earliest)

    latest_min = 1440
    if latest_end:
        latest_min = to_minutes(latest_end)

    start_from = 0
    if earliest:
        start_from = ((earliest_min + 14) // 15) * 15

    start_to = 1440 - minutes
    if latest_end:
        start_to = latest_min - minutes
    if start_to > 1440 - minutes:
        start_to = 1440 - minutes

    for day in days:
        user_info = api.read_calendar("", day)
        user_offset = to_offset(user_info.get("utc_offset", ""))
        user_wh = user_info.get("working_hours", "00:00-24:00")
        user_start, user_end = parse_hours(user_wh)

        windows = []
        clip_interval(user_start, user_end, windows)

        blocked = []

        user_day = day_entry(user_info)
        for event in user_day.get("events", []):
            if event.get("show_as", "busy") != "free":
                clip_interval(to_minutes(event["start"]), to_minutes(event["end"]), blocked)

        for person in attendees:
            info = api.read_calendar(person, day)
            person_offset = to_offset(info.get("utc_offset", ""))
            delta = user_offset - person_offset

            wh = info.get("working_hours", "00:00-24:00")
            ws, we = parse_hours(wh)
            clip_interval(ws + delta, we + delta, windows)

            person_day = day_entry(info)
            for event in person_day.get("events", []):
                if event.get("show_as", "busy") != "free":
                    clip_interval(to_minutes(event["start"]) + delta,
                                  to_minutes(event["end"]) + delta,
                                  blocked)

        starts = []
        if start_from <= start_to:
            for start in range(start_from, start_to + 1, 15):
                end = start + minutes
                ok = True

                for ws, we in windows:
                    if start < ws or end > we:
                        ok = False
                        break

                if ok:
                    for bs, be in blocked:
                        if max(start, bs) < min(end, be):
                            ok = False
                            break

                if ok:
                    starts.append("%02d:%02d" % (start // 60, start % 60))

        if starts:
            result[day] = starts

    return {"starts": result}
