def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_text(value):
        hour = value // 60
        minute = value % 60
        return str(hour).zfill(2) + ":" + str(minute).zfill(2)

    def next_quarter(value):
        remainder = value % 15
        if remainder == 0:
            return value
        return value + (15 - remainder)

    def parse_hours(text):
        if type(text) != str or "-" not in text:
            return 0, 24 * 60
        parts = text.split("-", 1)
        return to_minutes(parts[0]), to_minutes(parts[1])

    def choose_day(data, day):
        if type(data) == dict and "days" in data:
            for item in data["days"]:
                if item.get("day") == day:
                    hours = item.get("working_hours", data.get("working_hours", "09:00-17:00"))
                    return item, hours
        if type(data) == dict and data.get("day") == day:
            return data, data.get("working_hours", "09:00-17:00")
        return None, "09:00-17:00"

    people = [""]
    for person in attendees:
        if person not in people:
            people.append(person)

    calendars = {}
    for person in people:
        try:
            calendars[person] = api.read_calendar(person, "")
        except TypeError:
            calendars[person] = api.read_calendar(person)

    result = {"starts": {}}

    for day in days:
        busy = []
        start_limit = 0 if earliest == "" else to_minutes(earliest)
        end_limit = 24 * 60 if latest_end == "" else to_minutes(latest_end)

        for person in people:
            data = calendars[person]
            daydata, hours = choose_day(data, day)

            if daydata is None:
                try:
                    data = api.read_calendar(person, day)
                except TypeError:
                    data = api.read_calendar(person)
                calendars[person] = data
                daydata, hours = choose_day(data, day)

