    def round_up_quarter(total):
        if total % 15 == 0:
            return total
        return total + (15 - total % 15)

    def clip_interval(start, end):
        if end <= 0 or start >= 1440:
            return None
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if start >= end:
            return None
        return [start, end]

    unique_attendees = []
    for name in attendees:
        if name not in unique_attendees:
            unique_attendees.append(name)

