            work_parts = working_text.split("-")
            offset = parse_offset(info["utc_offset"]) if "utc_offset" in info else 0
            shift = user_offset - offset

            work_start = parse_clock(work_parts[0]) + shift
            work_end = parse_clock(work_parts[1]) + shift
            work_interval = clip_interval(work_start, work_end)

            busy = []
            for event in day_info.get("events", []):
                if event.get("show_as") != "free":
                    event_start = parse_clock(event["start"]) + shift
                    event_end = parse_clock(event["end"]) + shift
                    interval = clip_interval(event_start, event_end)
                    if interval is not None:
                        busy.append(interval)

            people.append({"work": work_interval, "busy": busy})

        earliest_start = 0 if earliest == "" else parse_clock(earliest)
        earliest_start = round_up_quarter(earliest_start)
        if earliest_start < 0:
            earliest_start = 0

        latest_finish = 1440 if latest_end == "" else parse_clock(latest_end)
        latest_start = latest_finish - minutes
        if latest_start > 1440 - minutes:
            latest_start = 1440 - minutes

        if latest_start < earliest_start:
            continue

        starts = []
        current = earliest_start
        while current <= latest_start:
            end_time = current + minutes
            if end_time <= 1440:
                good = True
                for person in people:
                    work = person["work"]
