def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parseTime(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def makeTime(value):
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def roundQuarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def chooseDayItem(data, day):
        dayList = data.get("days", [])
        key = day[0:3].lower()
        for item in dayList:
            if item.get("day", "").lower() == key:
                return item
        if len(dayList) > 0:
            return dayList[0]
        return {"events": []}

    def freeIntervals(data, day):
        if not data:
            return []
        work = data.get("working_hours", "00:00-23:59")
        parts = work.split("-")
        workStart = parseTime(parts[0])
        workEnd = parseTime(parts[1])
        item = chooseDayItem(data, day)
        busy = []
        for event in item.get("events", []):
            if event.get("show_as") != "free":
                s = parseTime(event.get("start", "00:00"))
                e = parseTime(event.get("end", "00:00"))
                if e > workStart and s < workEnd:
                    if s < workStart:
                        s = workStart
                    if e > workEnd:
                        e = workEnd
                    if s < e:
                        busy.append([s, e])
        busy.sort(key=lambda x: x[0])
        merged = []
        for s, e in busy:
            if len(merged) == 0 or s > merged[-1][1]:
                merged.append([s, e])
            else:
                if e > merged[-1][1]:
                    merged[-1][1] = e
        free = []
        cur = workStart
        for s, e in merged:
            if s > cur:
                free.append([cur, s])
            if e > cur:
                cur = e
            if cur >= workEnd:
                break
        if cur < workEnd:
            free.append([cur, workEnd])
        return free

    def intersect(a, b):
        out = []
        i = 0
        j = 0
        while i < len(a) and j < len(b):
            s = a[i][0]
            if b[j][0] > s:
                s = b[j][0]
            e = a[i][1]
            if b[j][1] < e:
                e = b[j][1]
            if s < e:
                out.append([s, e])
            if a[i][1] < b[j][1]:
                i += 1
            else:
                j += 1
        return out

    people = [""]
    seen = {"": True}
    for name in attendees:
        if name not in seen:
            seen[name] = True
            people.append(name)

    result = {"starts": {}}
    earliestMin = parseTime(earliest) if earliest else None
    latestMin = parseTime(latest_end) if latest_end else None

    for day in days:
        allFree = []
        for person in people:
            data = api.read_calendar(person, day)
            allFree.append(freeIntervals(data, day))
        common = allFree[0] if len(allFree) > 0 else []
        for idx in range(1, len(allFree)):
            common = intersect(common, allFree[idx])
            if len(common) == 0:
                break

        starts = []
        for s, e in common:
            start = s
            if earliestMin is not None and earliestMin > start:
                start = earliestMin
            start = roundQuarter(start)
            endLimit = e - minutes
            if latestMin is not None and latestMin - minutes < endLimit:
                endLimit = latestMin - minutes
            while start <= endLimit:
                if start + minutes <= e:
                    starts.append(makeTime(start))
                start += 15

        if len(starts) > 0:
            result["starts"][day] = starts

    return result
