        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def roundUpQuarter(value):
        remainder = value % 15
        if remainder == 0:
            return value
        return value + (15 - remainder)

    def convertToUserClock(value, personOffset, userOffset):
        return value + userOffset - personOffset

    startsByDay = {}

    for day in days:
        userCal = api.read_calendar("", day)
        userDays = userCal.get("days", [])
