            if not cal.get("days", []):
                valid = False
                break
            allCalendars.append(cal)

        if not valid:
            continue

        busyRanges = []
        workStarts = []
        workEnds = []

        for cal in allCalendars:
            personOffset = parseOffset(cal.get("utc_offset", "+00:00"))
            dayInfo = cal["days"][0]

            hours = cal.get("working_hours", "")
            if not hours:
