            startWork = convertToUserClock(toMinutes(pieces[0]), personOffset, userOffset)
            endWork = convertToUserClock(toMinutes(pieces[1]), personOffset, userOffset)
            workStarts.append(startWork)
            workEnds.append(endWork)

            for event in dayInfo.get("events", []):
                if event.get("show_as") == "busy":
                    startBusy = convertToUserClock(toMinutes(event["start"]), personOffset, userOffset)
                    endBusy = convertToUserClock(toMinutes(event["end"]), personOffset, userOffset)
                    busyRanges.append([startBusy, endBusy])

        if not valid:
            continue

        startLimit = max(workStarts)
        endLimit = min(workEnds)

        if earliest != "":
            startLimit = max(startLimit, toMinutes(earliest))
        if latest_end != "":
            endLimit = min(endLimit, toMinutes(latest_end))

        startLimit = roundUpQuarter(startLimit)
        lastStart = endLimit - minutes

        dayStarts = []
        current = startLimit
        while current <= lastStart:
            free = True
            for busy in busyRanges:
                if current < busy[1] and current + minutes > busy[0]:
                    free = False
                    break
            if free:
                dayStarts.append(toTime(current))
            current += 15

        if dayStarts:
            startsByDay[dayKey] = dayStarts

    return {"starts": startsByDay}
