    def format_time(n):
        h = n // 60
        m = n % 60
        return ("0" + str(h))[-2:] + ":" + ("0" + str(m))[-2:]

    def parse_offset(t):
        sign = 1
        i = 0
        if t and (t[0] == "+" or t[0] == "-"):
            if t[0] == "-":
                sign = -1
            i = 1
        return sign * (int(t[i:i + 2]) * 60 + int(t[i + 3:i + 5]))

    def local_parts(start, end):
        if end >= start:
            return [[start, end]]
        return [[start, 1440], [0, end]]

    def shift_clip(start, end, delta):
        parts = local_parts(start, end)
        out = []
        for part in parts:
            s = part[0] + delta
            e = part[1] + delta
            if e <= 0 or s >= 1440:
                continue
            if s < 0:
                s = 0
            if e > 1440:
                e = 1440
            if s < e:
                out.append([s, e])
        return out

    def intersect_ranges(a, b):
        out = []
        i = 0
        j = 0
        while i < len(a) and j < len(b):
            s = a[i][0] if a[i][0] > b[j][0] else b[j][0]
            e = a[i][1] if a[i][1] < b[j][1] else b[j][1]
            if s < e:
                out.append([s, e])
            if a[i][1] < b[j][1]:
                i += 1
            else:
                j += 1
        return out

    def subtract_range(ranges, block):
        out = []
        for r in ranges:
            if block[1] <= r[0] or block[0] >= r[1]:
                out.append([r[0], r[1]])
            else:
                if block[0] > r[0]:
                    out.append([r[0], block[0] if block[0] < r[1] else r[1]])
                if block[1] < r[1]:
                    out.append([block[1] if block[1] > r[0] else r[0], r[1]])
        return out

    if not days:
        return {"starts": {}}

    user_data = api.read_calendar("", days[0])
    user_offset = parse_offset(user_data["utc_offset"])

    people = [""]
    for name in attendees:
        if name not in people:
            people.append(name)

    earliest_min = parse_time(earliest) if earliest else 0
    latest_min = parse_time(latest_end) if latest_end else 1440
    if latest_min > 1440:
        latest_min = 1440

    result = {}
    for day in days:
        day_free = None
        for person in people:
            data = api.read_calendar(person, day)
            person_offset = parse_offset(data["utc_offset"])
            delta = user_offset - person_offset

            working = data["working_hours"]
            work_start = parse_time(working[:5])
            work_end = parse_time(working[6:])
            free = []
            for part in shift_clip(work_start, work_end, delta):
                free.append([part[0], part[1]])

            note = ""
            if "note" in data:
                note = data["note"].lower()
            pad = 15 if "15 minutes free before and after" in note else 0

            day_rows = data["days"]
            events = []
            if day_rows:
                events = day_rows[0]["events"]

            for ev in events:
                if ev.get("show_as") == "free":
                    continue
                ev_start = parse_time(ev["start"]) - pad
                ev_end = parse_time(ev["end"]) + pad
                blocks = shift_clip(ev_start, ev_end, delta)
                for block in blocks:
                    free = subtract_range(free, block)

            if day_free is None:
                day_free = free
            else:
                day_free = intersect_ranges(day_free, free)

            if not day_free:
                break

        starts = []
        if day_free:
            for r in day_free:
                start = r[0]
                if start < earliest_min:
