                    e = base + parse_time(event["end"]) + delta
                    if e <= s:
                        e += 1440
                    busy.append((s, e))

        calendars.append({"working": working, "busy": busy})

    start_min = 0
    if earliest != "":
        start_min = ceil_quarter(parse_time(earliest))

    end_limit = 24 * 60
    if latest_end != "":
        end_limit = parse_time(latest_end)

    result = {}
    for day in days:
        if day not in day_index:
            continue

        base = day_index[day] * 1440
        first = start_min
        if first < 0:
            first = 0
        if first % 15 != 0:
            first = ceil_quarter(first)

        last = end_limit - minutes
        if last > 24 * 60 - minutes:
            last = 24 * 60 - minutes

        starts = []
        if last >= first:
            cand = first
            while cand <= last:
                cand_abs = base + cand
                cand_end = cand_abs + minutes
                ok = True

                for cal in calendars:
                    inside = False
                    for ws, we in cal["working"]:
                        if cand_abs >= ws and cand_end <= we:
                            inside = True
                            break
                    if not inside:
                        ok = False
                        break

                    for bs, be in cal["busy"]:
