def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        return str(total // 60).zfill(2) + ":" + str(total % 60).zfill(2)

    def round_up_quarter(total):
        remainder = total % 15
        if remainder == 0:
            return total
        return total + (15 - remainder)

    def parse_hours(text):
        parts = text.split("-")
        return to_minutes(parts[0].strip()), to_minutes(parts[1].strip())

    def parse_value_minutes(value):
        if type(value) == int:
            return value
        if type(value) != str:
            return -1
        s = value.strip()
        if not s:
            return -1
        sign = 1
        if s[0] == "+":
            s = s[1:]
        elif s[0] == "-":
            sign = -1
            s = s[1:]
        if not s:
            return -1
        if ":" in s:
            parts = s.split(":")
            if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
                return sign * (int(parts[0]) * 60 + int(parts[1]))
        digits = ""
        for ch in s:
            if ch.isdigit():
                digits += ch
            else:
                break
        if not digits:
            return -1
        if len(digits) <= 2:
            return sign * int(digits) * 60
        if len(digits) == 3 or len(digits) == 4:
            head = digits[:-2]
            tail = digits[-2:]
            if head.isdigit() and tail.isdigit():
                return sign * (int(head) * 60 + int(tail))
        return sign * int(digits)

    def parse_offset(text):
        if type(text) == int:
            return text
        if type(text) != str:
            return 0
        s = text.strip().upper()
        if not s or s == "UTC" or s == "GMT" or s == "Z":
            return 0
        if s.startswith("UTC"):
            s = s[3:].strip()
        elif s.startswith("GMT"):
            s = s[3:].strip()
        sign = 1
        if s and s[0] == "+":
            s = s[1:]
        elif s and s[0] == "-":
            sign = -1
            s = s[1:]
        if not s:
            return 0
        if ":" in s:
            parts = s.split(":")
            if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
                return sign * (int(parts[0]) * 60 + int(parts[1]))
        digits = ""
        for ch in s:
            if ch.isdigit():
                digits += ch
            else:
                break
        if not digits:
            return 0
        if len(digits) <= 2:
            return sign * int(digits) * 60
        if len(digits) == 3 or len(digits) == 4:
            head = digits[:-2]
            tail = digits[-2:]
            if head.isdigit() and tail.isdigit():
                return sign * (int(head) * 60 + int(tail))
        return sign * int(digits)

    def calendar_offset(cal):
        if type(cal) != dict:
            return 0
        keys = ["utc_offset", "timezone_offset", "offset", "tz_offset", "timezone", "tz"]
        for key in keys:
            if key in cal:
                return parse_offset(cal.get(key))
        return 0

    def buffer_from_text(text):
        before = 0
        after = 0
        if type(text) != str:
            return before, after
        s = text.lower()
        for ch in [",", ";", "(", ")", "[", "]", ".", ":", "/", "_", "\n", "\t"]:
            s = s.replace(ch, " ")
        tokens = s.split()
        for i in range(len(tokens)):
            num = parse_value_minutes(tokens[i])
            if num >= 0:
                left = i - 2
                if left < 0:
                    left = 0
                right = i + 3
                if right > len(tokens):
                    right = len(tokens)
                window = tokens[left:right]
                has_before = False
                has_after = False
                has_buffer = False
                for word in window:
                    if word == "before" or word == "pre" or word == "lead" or word == "leading":
                        has_before = True
                    if word == "after" or word == "post" or word == "trailing" or word == "wrap":
                        has_after = True
                    if word == "buffer" or word == "padding" or word == "pad" or word == "margin":
                        has_buffer = True
                if has_before:
                    if num > before:
                        before = num
                if has_after:
                    if num > after:
                        after = num
                if has_buffer and not has_before and not has_after:
                    if num > before:
                        before = num
                    if num > after:
                        after = num
        return before, after

    def item_buffer(item):
        before = 0
        after = 0
        if type(item) != dict:
            return before, after
        for key in item:
            low = str(key).lower()
            value = item.get(key)
            num = parse_value_minutes(value)
            if num >= 0:
                if "before" in low or "pre" in low or "lead" in low:
                    if num > before:
                        before = num
                elif "after" in low or "post" in low or "wrap" in low:
                    if num > after:
                        after = num
                elif "buffer" in low or "padding" in low or "pad" in low or "margin" in low:
                    if num > before:
                        before = num
                    if num > after:
                        after = num
            if low == "notes" or low == "note" or low == "comment" or low == "comments" or low == "description" or low == "desc" or low == "text" or low == "memo" or low == "details":
                tb, ta = buffer_from_text(value if type(value) == str else str(value))
                if tb > before:
                    before = tb
                if ta > after:
                    after = ta
        return before, after

    def get_day_entries(cal, day):
        entries = []
        if type(cal) != dict:
            return entries
        day_key = day.lower()
        days_data = cal.get("days", [])
        if type(days_data) == dict:
            value = days_data.get(day, [])
            if type(value) == list:
                for entry in value:
                    if type(entry) == dict:
                        entries.append(entry)
            elif type(value) == dict:
                entries.append(value)
        elif type(days_data) == list:
            for entry in days_data:
                if type(entry) == dict:
                    entry_day = entry.get("day", "")
                    if type(entry_day) == str and entry_day.lower() == day_key:
                        entries.append(entry)
        if not entries:
            entry_day = cal.get("day", "")
            if type(entry_day) == str and entry_day.lower() == day_key:
                entries.append(cal)
        return entries

    def merge_busy(intervals, start_limit, end_limit):
        items = []
        for interval in intervals:
            start = interval[0]
            end = interval[1]
            if end > start_limit and start < end_limit:
                if start < start_limit:
                    start = start_limit
                if end > end_limit:
                    end = end_limit
                if start < end:
                    items.append([start, end])
        items.sort()
        merged = []
        for start, end in items:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                if end > merged[-1][1]:
                    merged[-1][1] = end
        return merged

    people = []
    seen = {}
    for person in [""] + attendees:
        if person not in seen:
            seen[person] = 1
            people.append(person)

    calendars = {}
    offsets = {}
    for person in people:
        cal = api.read_calendar(person, "")
        if type(cal) != dict:
            cal = {}
        calendars[person] = cal
        offsets[person] = calendar_offset(cal)

    user_offset = offsets.get("", 0)

    result = {"starts": {}}

    for day in days:
        day_start = 24 * 60
        day_end = 0
        busy_intervals = []
        can_meet = True

        for person in people:
            cal = calendars.get(person, {})
            person_offset = offsets.get(person, 0)
            delta = user_offset - person_offset

            entries = get_day_entries(cal, day)
            work_text = cal.get("working_hours", "")
            if len(entries) > 0:
                for entry in entries:
                    if "working_hours" in entry:
                        work_text = entry.get("working_hours", work_text)
                        break
            if not work_text:
                work_text = "00:00-23:59"

            work_start, work_end = parse_hours(work_text)
            if work_end < work_start:
                work_end += 24 * 60

            work_start = work_start + delta
            work_end = work_end + delta

            if earliest:
                e = to_minutes(earliest)
                if e > work_start:
                    work_start = e
            if latest_end:
                l = to_minutes(latest_end)
                if l < work_end:
                    work_end = l

            if work_start > day_start:
                day_start = work_start
            if work_end < day_end or day_end == 0:
                day_end = work_end

            base_before, base_after = item_buffer(cal)

            for entry in entries:
                entry_before, entry_after = item_buffer(entry)
                events = entry.get("events", [])
                if type(events) != list:
                    events = []
                for event in events:
                    show_as = event.get("show_as", "busy")
                    if type(show_as) == str and show_as.lower() == "free":
                        continue
                    start_text = event.get("start", "")
                    end_text = event.get("end", "")
                    if type(start_text) != str or type(end_text) != str:
                        continue
                    start_local = to_minutes(start_text)
                    end_local = to_minutes(end_text)
                    if end_local <= start_local:
                        end_local += 24 * 60

                    event_before, event_after = item_buffer(event)
                    before = base_before
                    if entry_before > before:
                        before = entry_before
                    if event_before > before:
                        before = event_before

                    after = base_after
                    if entry_after > after:
                        after = entry_after
                    if event_after > after:
                        after = event_after

                    start_local = start_local - before
                    end_local = end_local + after

                    start_user = start_local + delta
                    end_user = end_local + delta

                    if end_user > 0 and start_user < 24 * 60:
                        if start_user < 0:
                            start_user = 0
                        if end_user > 24 * 60:
                            end_user = 24 * 60
                        if start_user < end_user:
                            busy_intervals.append([start_user, end_user])

        if day_start < 0:
            day_start = 0
        if day_end > 24 * 60:
            day_end = 24 * 60

        if day_end - day_start < minutes:
            continue

        first_start = round_up_quarter(day_start)
        last_start = day_end - minutes
        if first_start > last_start:
            continue

        merged_busy = merge_busy(busy_intervals, day_start, day_end)

        starts = []
        start_time = first_start
        while start_time <= last_start:
            end_time = start_time + minutes
            ok = True
            for busy_start, busy_end in merged_busy:
                if start_time < busy_end and end_time > busy_start:
                    ok = False
                    break
            if ok:
