                "timeZoneOffset", "utcOffset"
            ]
            for key in keys:
                if key in node:
                    off = parse_offset_value(node.get(key))
                    if off is not None:
                        return off
            for key in node:
                low = str(key).lower()
                if "offset" in low or "timezone" in low or low.endswith("tz") or low.endswith("utc") or low.endswith("gmt"):
                    off = parse_offset_value(node.get(key))
                    if off is not None:
                        return off
        elif type(node) == list:
            for item in node:
                off = direct_offset(item)
                if off is not None:
                    return off
        elif type(node) == str or type(node) == int:
            return parse_offset_value(node)
        return None

    def parse_clock(text):
        if type(text) == bool:
            return -1
        if type(text) == int:
            if 0 <= text <= 24 * 60:
                return text
            return -1
        if type(text) == list:
            for item in text:
                value = parse_clock(item)
                if value >= 0:
                    return value
            return -1
        if type(text) == dict:
            keys = [
                "dateTime", "datetime", "date_time", "time", "value", "start", "end",
                "begin", "from", "to", "dtstart", "dtend", "start_time", "end_time",
                "startTime", "endTime"
            ]
            for key in keys:
                if key in text:
                    value = parse_clock(text.get(key))
                    if value >= 0:
                        return value
            for key in text:
                value = parse_clock(text.get(key))
                if value >= 0:
                    return value
            return -1
        if type(text) != str:
            return -1

        s = text.strip()
        if not s:
            return -1

        cleaned = s.replace(".", " ").replace(",", " ").replace(";", " ").replace("(", " ").replace(")", " ")
        cleaned = cleaned.replace("[", " ").replace("]", " ").replace("{", " ").replace("}", " ").replace("T", " ")
        tokens = cleaned.split()

        for i in range(len(tokens)):
            tok = tokens[i]
            low = tok.lower()

            if low.endswith("am") or low.endswith("pm"):
                suffix = low[-2:]
                body = tok[:-2].strip()
                value = parse_clock(body)
                if value >= 0:
                    hour = value // 60
                    minute = value % 60
                    if suffix == "am":
                        if hour == 12:
                            hour = 0
                    else:
                        if hour != 12:
                            hour += 12
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if low in ["am", "pm"] and i > 0:
                value = parse_clock(tokens[i - 1])
                if value >= 0:
                    hour = value // 60
                    minute = value % 60
                    if low == "am":
                        if hour == 12:
                            hour = 0
                    else:
                        if hour != 12:
                            hour += 12
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if ":" in tok:
                parts = tok.split(":")
                if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                    hour = int(parts[0].strip())
                    minute = int(parts[1].strip()[:2])
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if tok.isdigit():
                num = int(tok)
                if 0 <= num <= 24:
                    return num * 60
                if len(tok) == 3 or len(tok) == 4:
                    hour = int(tok[:-2])
                    minute = int(tok[-2:])
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute
        return -1

    def parse_duration(value, allow_clock):
        if type(value) == bool:
            return -1
        if type(value) == int:
            if value >= 0:
                return value
            return -1
        if type(value) == list:
            for item in value:
                num = parse_duration(item, allow_clock)
                if num >= 0:
                    return num
            return -1
        if type(value) == dict:
            total = 0
            found = False
            for key in value:
                low = str(key).lower()
                sub = value.get(key)
                if low == "duration":
                    num = parse_duration(sub, allow_clock)
                    if num >= 0:
                        return num
                elif low.endswith("hour") or low.endswith("hours") or low == "h":
                    num = parse_duration(sub, False)
                    if num >= 0:
                        if type(sub) == str and ("h" in sub.lower() or "hour" in sub.lower()):
                            total += num
                        else:
                            total += num * 60
                        found = True
                elif low.endswith("minute") or low.endswith("minutes") or low.endswith("mins") or low.endswith("min") or low == "m":
                    num = parse_duration(sub, False)
                    if num >= 0:
                        total += num
                        found = True
                elif low.endswith("second") or low.endswith("seconds") or low.endswith("secs") or low.endswith("sec") or low == "s":
                    num = parse_duration(sub, False)
                    if num >= 0:
                        total += num // 60
                        found = True
            if found:
                return total
            return -1
        if type(value) != str:
            return -1

        s = value.strip().lower()
        if not s:
            return -1

        sign = 1
        if s[0] == "+":
            s = s[1:].strip()
        elif s[0] == "-":
            sign = -1
            s = s[1:].strip()
        if not s:
            return -1

        if s.startswith("pt"):
            s = s[2:]

        if allow_clock and ":" in s:
            parts = s.split(":")
            if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                return sign * (int(parts[0].strip()) * 60 + int(parts[1].strip()[:2]))
        if not allow_clock and ":" in s:
            return -1

        total = 0
        num = ""
        found = False
        i = 0
        while i < len(s):
            ch = s[i]
            if ch.isdigit():
                num += ch
            else:
                if num:
                    j = i
                    while j < len(s) and s[j] == " ":
                        j += 1
                    tail = s[j:]
                    if tail.startswith("hour") or tail.startswith("hours") or tail.startswith("hr") or tail.startswith("hrs") or tail.startswith("h"):
                        total += int(num) * 60
                        found = True
                        num = ""
                        i = j
                    elif tail.startswith("minute") or tail.startswith("minutes") or tail.startswith("min") or tail.startswith("m"):
                        total += int(num)
                        found = True
                        num = ""
                        i = j
                    elif tail.startswith("second") or tail.startswith("seconds") or tail.startswith("sec") or tail.startswith("s"):
                        total += int(num) // 60
                        found = True
                        num = ""
                        i = j
                    else:
                        if found:
                            total += int(num)
                            num = ""
                        else:
                            return sign * int(num)
            i += 1

        if num:
            if found:
                total += int(num)
            else:
                return sign * int(num)

        if found:
            return sign * total
        return -1

    def token_duration(tokens, index):
        tok = tokens[index]
        low = tok.lower()
        if ":" in tok:
            return -1
        if low.endswith("am") or low.endswith("pm"):
            return -1
        num = parse_duration(tok, False)
        if num >= 0 and tok.isdigit():
            if index + 1 < len(tokens):
                nxt = tokens[index + 1].lower()
                if nxt.startswith("hour") or nxt.startswith("hr") or nxt == "h" or nxt.startswith("hours") or nxt.startswith("hrs"):
                    return int(tok) * 60
                if nxt.startswith("minute") or nxt.startswith("min") or nxt == "m" or nxt.startswith("minutes") or nxt.startswith("mins"):
                    return int(tok)
                if nxt.startswith("second") or nxt.startswith("sec") or nxt == "s" or nxt.startswith("seconds") or nxt.startswith("secs"):
                    return int(tok) // 60
            return num
        return num

    def buffer_from_text(text):
        before = 0
        after = 0
        if type(text) != str:
            return before, after
        s = text.lower()
        for ch in [",", ";", "(", ")", "[", "]", ".", ":", "/", "_", "\n", "\t", "|", "-", "—", "–"]:
            s = s.replace(ch, " ")
        tokens = s.split()
        for i in range(len(tokens)):
            num = token_duration(tokens, i)
            if num < 0:
                continue
            left = i - 3
            if left < 0:
                left = 0
            right = i + 4
            if right > len(tokens):
                right = len(tokens)
            window = tokens[left:right]
            has_before = False
            has_after = False
            has_buffer = False
            for word in window:
                if word == "before" or word == "pre" or word == "lead" or word == "leading":
                    has_before = True
                if word == "after" or word == "post" or word == "trailing" or word == "wrap" or word == "following" or word == "trail":
                    has_after = True
                if word == "buffer" or word == "padding" or word == "pad" or word == "margin":
                    has_buffer = True
            if has_before and num > before:
                before = num
            if has_after and num > after:
                after = num
            if has_buffer and not has_before and not has_after:
                if num > before:
                    before = num
                if num > after:
                    after = num
        return before, after

    def item_buffer(node):
        before = 0
        after = 0
        if type(node) == dict:
            for key in node:
                low = str(key).lower()
                value = node.get(key)
                num = parse_duration(value, False)
                if num >= 0:
                    if "before" in low or "pre" in low or "lead" in low:
                        if num > before:
                            before = num
                    elif "after" in low or "post" in low or "wrap" in low or "trail" in low or "following" in low:
                        if num > after:
                            after = num
                    elif "buffer" in low or "padding" in low or "pad" in low or "margin" in low:
                        if num > before:
                            before = num
                        if num > after:
                            after = num
                if type(value) == str:
                    tb, ta = buffer_from_text(value)
                elif type(value) == dict or type(value) == list:
                    tb, ta = item_buffer(value)
                else:
                    tb = 0
                    ta = 0
                if tb > before:
                    before = tb
                if ta > after:
                    after = ta
        elif type(node) == list:
            for item in node:
                tb, ta = item_buffer(item)
                if tb > before:
                    before = tb
                if ta > after:
                    after = ta
        elif type(node) == str:
            tb, ta = buffer_from_text(node)
            if tb > before:
                before = tb
            if ta > after:
                after = ta
        return before, after

    def is_free_marker(node):
        if type(node) != dict:
            return False

        if "busy" in node:
            value = node.get("busy")
            if value is False:
                return True
            if type(value) == str:
                low = value.lower().strip()
                if low == "free" or low == "available" or low == "transparent" or low == "optional" or low == "false" or low == "no":
                    return True

        for key in ["free", "is_free", "available", "transparent", "optional"]:
            if key in node:
                value = node.get(key)
                if value is True:
                    return True
                if type(value) == str:
                    low = value.lower().strip()
                    if low == "true" or low == "yes" or low == "free" or low == "available" or low == "transparent" or low == "optional":
                        return True

        for key in ["show_as", "status", "availability", "visibility"]:
            if key in node:
                value = node.get(key)
                if type(value) == str:
                    low = value.lower().strip()
                    if low == "free" or low == "available" or low == "transparent" or low == "optional" or low == "canceled" or low == "cancelled" or low == "declined":
                        return True

        return False

    def has_busy_shape(node):
        if type(node) != dict:
            return False
        keys = [
            "start", "start_time", "begin", "from", "datetime", "date_time", "time",
            "dtstart", "startdate", "start_date", "starts", "end", "end_time", "finish",
            "to", "dtend", "enddate", "end_date", "ends", "duration", "all_day",
            "allday", "full_day", "fullday", "busy", "busy_times", "busy_periods",
            "busy_ranges", "busy_slots", "slots", "periods", "show_as", "status", "visibility"
        ]
        for key in node:
            low = str(key).lower()
            for name in keys:
                if low == name or low.endswith(name) or name in low:
                    return True
        return False

