    def pick_day_value(node, day):
        if type(node) != dict:
            return node
        if has_busy_shape(node) or is_free_marker(node):
            return node

        variants = [day, day.lower(), day.upper(), day.title(), day.capitalize()]
        if len(day) >= 3:
            variants.append(day[:3].lower())
            variants.append(day[:3].upper())
            variants.append(day[:3].title())

        if day.lower() == "mon":
            variants.extend(["monday", "Monday"])
        if day.lower() == "tue":
            variants.extend(["tuesday", "Tuesday", "tues", "Tues"])
        if day.lower() == "wed":
            variants.extend(["wednesday", "Wednesday"])
        if day.lower() == "thu":
            variants.extend(["thursday", "Thursday", "thur", "Thur", "thurs", "Thurs"])
        if day.lower() == "fri":
            variants.extend(["friday", "Friday"])

        for key in node:
            low = str(key).lower()
            for item in variants:
                item_low = item.lower()
                if low == item_low or low.endswith(item_low):
                    return node.get(key)
        return node

    def parse_range_string(text, inherited_offset):
        windows = []
        if type(text) != str:
            return windows
        s = text.strip()
        if not s:
            return windows

        s = s.replace("–", "-").replace("—", "-")
        s = s.replace(" until ", " - ").replace(" through ", " - ").replace(" to ", " - ")
        s = s.replace("\n", ";").replace(",", ";")

        parts = s.split(";")
        for part in parts:
            piece = part.strip()
            if not piece:
                continue

            candidates = []
            if " - " in piece:
                candidates.append(piece.find(" - "))
            i = 0
            while i < len(piece):
                if piece[i] == "-":
                    candidates.append(i)
                i += 1

            made = False
            for sep in candidates:
                if " - " in piece and sep == piece.find(" - "):
                    left = piece[:sep].strip()
                    right = piece[sep + 3:].strip()
                else:
                    left = piece[:sep].strip()
                    right = piece[sep + 1:].strip()
                if not left or not right:
                    continue
                start = parse_clock(left)
                end = parse_clock(right)
                if start >= 0 and end >= 0:
                    if end < start:
                        end += 24 * 60
                    off = inherited_offset
                    off0 = parse_offset_value(left)
                    if off0 is not None:
                        off = off0
                    off1 = parse_offset_value(right)
                    if off1 is not None:
                        off = off1
                    windows.append([start, end, off])
                    made = True
                    break
            if made:
                continue
        return windows

    def extract_raw_intervals(node, current_offset, free_mode):
        result = []
        if type(node) == list:
            if len(node) == 2 and type(node[0]) != dict and type(node[0]) != list and type(node[1]) != dict and type(node[1]) != list:
                start = parse_clock(node[0])
                end = parse_clock(node[1])
                if start >= 0 and end >= 0:
                    if end < start:
                        end += 24 * 60
                    off = direct_offset(node[0])
                    if off is None:
                        off = direct_offset(node[1])
                    if off is None:
                        off = current_offset
                    result.append([start, end, off])
            return result

        if type(node) == str:
            return parse_range_string(node, current_offset)

        if type(node) != dict:
            return result

        startNames = ["start", "begin", "from", "datetime", "dateTime", "time", "dtstart", "start_time", "startTime", "starttime", "start_date", "startDate"]
        endNames = ["end", "finish", "to", "dtend", "end_time", "endTime", "endtime", "end_date", "endDate"]

        if free_mode:
            startNames = startNames + ["available_from", "free_from", "open"]
            endNames = endNames + ["available_to", "free_to", "close"]

        startKey = ""
        endKey = ""
        for key in node:
            low = str(key).lower()
            if startKey == "" and name_match(low, startNames):
                startKey = key
            if endKey == "" and name_match(low, endNames):
                endKey = key

        if startKey != "" and endKey != "":
            start = parse_clock(node.get(startKey))
            end = parse_clock(node.get(endKey))
            if start >= 0 and end >= 0:
                if end < start:
                    end += 24 * 60
                off = direct_offset(node.get(startKey))
                if off is None:
                    off = direct_offset(node.get(endKey))
                if off is None:
                    off = current_offset
                result.append([start, end, off])
        elif startKey != "" and "duration" in node:
            duration = parse_duration(node.get("duration"), True)
            if duration >= 0:
                start = parse_clock(node.get(startKey))
                if start >= 0:
                    off = direct_offset(node.get(startKey))
                    if off is None:
                        off = current_offset
                    result.append([start, start + duration, off])
        elif endKey != "" and "duration" in node:
            duration = parse_duration(node.get("duration"), True)
            if duration >= 0:
                end = parse_clock(node.get(endKey))
                if end >= 0:
                    off = direct_offset(node.get(endKey))
                    if off is None:
                        off = current_offset
                    result.append([end - duration, end, off])

        if not free_mode:
            allDay = False
            if "all_day" in node:
                value = node.get("all_day")
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    allDay = True
            if "allday" in node:
                value = node.get("allday")
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    allDay = True
            if "full_day" in node:
                value = node.get("full_day")
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    allDay = True
            if "fullDay" in node:
                value = node.get("fullDay")
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    allDay = True
            if allDay:
                result.append([0, 24 * 60, current_offset])

        return result

    def add_busy(start, end, offset, before, after, holder):
        if start is None or end is None:
            return
        s = start - before
        e = end + after
        if e <= 0 or s >= 24 * 60:
            return
        if s < 0:
            s = 0
        if e > 24 * 60:
            e = 24 * 60
        if s < e:
            holder.append([s, e, offset])

    def add_free(start, end, offset, holder):
        if start is None or end is None:
            return
        s = start
        e = end
        if e <= 0 or s >= 24 * 60:
            return
        if s < 0:
            s = 0
        if e > 24 * 60:
            e = 24 * 60
        if s < e:
            holder.append([s, e, offset])

    def scan_calendar(node, day, inherited_offset, before, after, busy_holder, free_holder, free_mode):
        if type(node) == list:
            if len(node) == 2 and type(node[0]) != dict and type(node[0]) != list and type(node[1]) != dict and type(node[1]) != list:
                start = parse_clock(node[0])
                end = parse_clock(node[1])
                if start >= 0 and end >= 0:
                    if end < start:
                        end += 24 * 60
                    off = direct_offset(node[0])
                    if off is None:
                        off = direct_offset(node[1])
                    if off is None:
                        off = inherited_offset
                    if free_mode:
                        add_free(start, end, off, free_holder)
                    else:
                        add_busy(start, end, off, before, after, busy_holder)
                    return
            for item in node:
                scan_calendar(item, day, inherited_offset, before, after, busy_holder, free_holder, free_mode)
            return

        if type(node) != dict:
            if type(node) == str:
                parsed = parse_range_string(node, inherited_offset)
                for interval in parsed:
                    if free_mode:
                        add_free(interval[0], interval[1], interval[2], free_holder)
                    else:
                        add_busy(interval[0], interval[1], interval[2], before, after, busy_holder)
            return

        day_node = pick_day_value(node, day)
        if day_node is not node:
            scan_calendar(day_node, day, inherited_offset, before, after, busy_holder, free_holder, free_mode)
            return

        current_offset = direct_offset(node)
        if current_offset is None:
            current_offset = inherited_offset

        local_before, local_after = item_buffer(node)
        if local_before > before:
            before = local_before
        if local_after > after:
            after = local_after

        current_free = free_mode
        if not current_free:
            if is_free_marker(node):
                current_free = True
            elif has_free_container(node) and not has_busy_shape(node):
                current_free = True

        event_like = current_free or has_busy_shape(node) or has_free_container(node) or is_free_marker(node)
        if event_like:
            raw = extract_raw_intervals(node, current_offset, current_free)
            for interval in raw:
                if current_free:
                    add_free(interval[0], interval[1], interval[2], free_holder)
                else:
                    add_busy(interval[0], interval[1], interval[2], before, after, busy_holder)

        for key in node:
            value = node.get(key)
            low = str(key).lower()

            if type(value) == str:
                if is_note_key(low):
                    continue
                if is_free_container_key(low):
                    parsed = parse_range_string(value, current_offset)
                    for interval in parsed:
                        add_free(interval[0], interval[1], interval[2], free_holder)
                elif current_free or is_time_key(low) or is_busy_container_key(low):
                    parsed = parse_range_string(value, current_offset)
                    for interval in parsed:
                        if current_free:
                            add_free(interval[0], interval[1], interval[2], free_holder)
                        else:
                            add_busy(interval[0], interval[1], interval[2], before, after, busy_holder)
                continue

            if type(value) == dict or type(value) == list:
                if is_note_key(low):
                    continue
                child_free = current_free or is_free_container_key(low)
