                if low == "free" or low == "available" or low == "transparent" or low == "optional" or low == "false" or low == "no" or low == "canceled" or low == "cancelled" or low == "declined":
                    return True

        for key in ["free", "is_free", "available", "transparent", "optional"]:
            if key in node:
                value = node.get(key)
                if value is True:
                    return True
                if type(value) == str:
                    low = value.lower().strip()
                    if low == "true" or low == "yes" or low == "free" or low == "available" or low == "transparent" or low == "optional":
                        return True

        for key in ["show_as", "status", "availability", "visibility"]:
            if key in node:
                value = node.get(key)
                if type(value) == str:
                    low = value.lower().strip()
                    if low == "free" or low == "available" or low == "transparent" or low == "optional" or low == "canceled" or low == "cancelled" or low == "declined":
                        return True

        return False

    def text_buffer(text):
        before = 0
        after = 0
        if type(text) != str:
            return before, after

        s = text.lower()
        for ch in [",", ";", "(", ")", "[", "]", ".", ":", "/", "_", "\n", "\t", "|", "-", "–", "—"]:
            s = s.replace(ch, " ")
        tokens = s.split()

        before_words = ["before", "pre", "lead", "leading", "prior", "prep"]
        after_words = ["after", "post", "trailing", "trail", "following", "follow", "wrap", "lag"]
        both_words = ["buffer", "padding", "pad", "margin", "gap"]

        def token_minutes(tok):
            if tok.isdigit():
                return int(tok)
            if tok.endswith("hours") and tok[:-5].isdigit():
                return int(tok[:-5]) * 60
            if tok.endswith("hour") and tok[:-4].isdigit():
                return int(tok[:-4]) * 60
            if tok.endswith("hrs") and tok[:-3].isdigit():
                return int(tok[:-3]) * 60
            if tok.endswith("hr") and tok[:-2].isdigit():
                return int(tok[:-2]) * 60
            if tok.endswith("h") and tok[:-1].isdigit():
                return int(tok[:-1]) * 60
            if tok.endswith("minutes") and tok[:-7].isdigit():
                return int(tok[:-7])
            if tok.endswith("minute") and tok[:-6].isdigit():
                return int(tok[:-6])
            if tok.endswith("mins") and tok[:-4].isdigit():
                return int(tok[:-4])
            if tok.endswith("min") and tok[:-3].isdigit():
                return int(tok[:-3])
            if tok.endswith("m") and tok[:-1].isdigit():
                return int(tok[:-1])
            if tok.endswith("seconds") and tok[:-7].isdigit():
                return int(tok[:-7]) // 60
            if tok.endswith("second") and tok[:-6].isdigit():
                return int(tok[:-6]) // 60
            if tok.endswith("secs") and tok[:-4].isdigit():
                return int(tok[:-4]) // 60
            if tok.endswith("sec") and tok[:-3].isdigit():
                return int(tok[:-3]) // 60
            if tok.endswith("s") and tok[:-1].isdigit():
                return int(tok[:-1]) // 60
            return -1

        for i in range(len(tokens)):
            num = token_minutes(tokens[i])
            if num < 0:
                continue
            left = i - 3
            if left < 0:
                left = 0
            right = i + 4
            if right > len(tokens):
                right = len(tokens)
            window = tokens[left:right]
            has_before = False
            has_after = False
            has_both = False
            for word in window:
                if word in before_words:
                    has_before = True
                if word in after_words:
                    has_after = True
                if word in both_words:
                    has_both = True
            if has_both and not has_before and not has_after:
                if num > before:
                    before = num
                if num > after:
                    after = num
            else:
                if has_before and num > before:
                    before = num
                if has_after and num > after:
                    after = num
        return before, after

    def note_buffer(node):
        before = 0
        after = 0
        if type(node) == dict:
            for key in node:
                low = str(key).lower()
                value = node.get(key)
                if is_note_key(low):
                    tb, ta = note_buffer(value)
                    if tb > before:
                        before = tb
                    if ta > after:
                        after = ta
                else:
                    if low == "buffer" or low == "padding" or low == "gap" or low == "margin" or low == "lead_time" or low == "lag_time":
                        num = parse_duration(value)
                        if num < 0 and type(value) == str:
                            tb, ta = text_buffer(value)
                            if tb > before:
                                before = tb
                            if ta > after:
                                after = ta
                        else:
                            if num >= 0:
                                if num > before:
                                    before = num
                                if num > after:
                                    after = num
                    elif "before" in low or "pre" in low or "lead" in low:
                        num = parse_duration(value)
                        if num < 0 and type(value) == str:
                            tb, ta = text_buffer(value)
                            if tb > before:
                                before = tb
                        elif num >= 0 and num > before:
                            before = num
                    elif "after" in low or "post" in low or "trail" in low or "follow" in low or "lag" in low:
                        num = parse_duration(value)
                        if num < 0 and type(value) == str:
                            tb, ta = text_buffer(value)
                            if ta > after:
                                after = ta
                        elif num >= 0 and num > after:
                            after = num

                    if type(value) == dict or type(value) == list:
                        tb, ta = note_buffer(value)
                        if tb > before:
                            before = tb
                        if ta > after:
                            after = ta
        elif type(node) == list:
            for item in node:
                tb, ta = note_buffer(item)
                if tb > before:
                    before = tb
                if ta > after:
                    after = ta
        elif type(node) == str:
            tb, ta = text_buffer(node)
            if tb > before:
                before = tb
            if ta > after:
                after = ta
        return before, after

    def merge_intervals(intervals):
        items = []
        for item in intervals:
            if type(item) != list or len(item) < 2:
                continue
            start = item[0]
            end = item[1]
            if start is None or end is None:
                continue
            if end > start:
                items.append([start, end])
        items.sort()
        merged = []
        for start, end in items:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            elif end > merged[-1][1]:
                merged[-1][1] = end
        return merged

    def subtract_intervals(base, cuts):
        cuts = merge_intervals(cuts)
        result = []
        for start, end in base:
            pos = start
            for cut_start, cut_end in cuts:
                if cut_end <= pos:
                    continue
                if cut_start >= end:
                    break
                if cut_start > pos:
                    right = cut_start
                    if right > end:
                        right = end
                    if right > pos:
                        result.append([pos, right])
                if cut_end > pos:
                    pos = cut_end
                if pos >= end:
                    break
            if pos < end:
                result.append([pos, end])
        return merge_intervals(result)

    def intersect_intervals(left, right):
        left = merge_intervals(left)
        right = merge_intervals(right)
        result = []
        i = 0
        j = 0
        while i < len(left) and j < len(right):
            start = left[i][0]
            if right[j][0] > start:
                start = right[j][0]
            end = left[i][1]
            if right[j][1] < end:
                end = right[j][1]
            if start < end:
                result.append([start, end])
            if left[i][1] < right[j][1]:
                i += 1
            else:
                j += 1
        return merge_intervals(result)

    def add_interval(start, end, offset, before, after, user_offset, holder, free_mode):
        if start is None or end is None:
            return
        if end < start:
            end += 24 * 60
        if offset is None:
            offset = user_offset
        delta = user_offset - offset
        s = start + delta
        e = end + delta
        if not free_mode:
            s -= before
            e += after
        if e <= 0 or s >= 24 * 60:
            return
        if s < 0:
            s = 0
        if e > 24 * 60:
            e = 24 * 60
        if s < e:
            holder.append([s, e])

    def parse_range_string(text, current_offset, before, after, user_offset, holder, free_mode):
        if type(text) != str:
            return
        s = text.strip()
        if not s:
            return

        s = s.replace("–", "-").replace("—", "-")
        s = s.replace("\n", ";")
        parts = s.split(";")
        for part in parts:
            piece = part.strip()
            if not piece:
                continue

            candidates = []
            for token in [" - ", " to ", " until ", " through "]:
                idx = piece.find(token)
                if idx >= 0:
                    candidates.append([idx, len(token)])

            # Also allow a single bare hyphen when it is the only one in the piece.
            if piece.count("-") == 1:
                idx = piece.find("-")
                if idx > 0 and idx + 1 < len(piece):
                    candidates.append([idx, 1])

            made = False
            for item in candidates:
                idx = item[0]
                size = item[1]
                left = piece[:idx].strip()
                right = piece[idx + size:].strip()
                if not left or not right:
                    continue
                start = parse_clock(left)
                end = parse_clock(right)
                if start >= 0 and end >= 0:
                    off = current_offset
                    off0 = parse_offset_value(left)
                    if off0 is not None:
                        off = off0
                    off1 = parse_offset_value(right)
                    if off1 is not None:
                        off = off1
                    add_interval(start, end, off, before, after, user_offset, holder, free_mode)
                    made = True
                    break
            if made:
                continue

    def extract_interval(node, current_offset, free_mode):
        if type(node) != dict:
            return None

        start_names = [
            "start", "begin", "from", "datetime", "dateTime", "time", "dtstart",
            "start_time", "startTime", "starttime", "start_date", "startDate"
        ]
        end_names = [
            "end", "finish", "to", "dtend", "end_time", "endTime", "endtime",
            "end_date", "endDate"
        ]
        if free_mode:
            start_names = start_names + ["available_from", "free_from", "open"]
            end_names = end_names + ["available_to", "free_to", "close"]

        start_key = ""
        end_key = ""
        for key in node:
            low = str(key).lower()
            if start_key == "" and name_match(low, start_names):
                start_key = key
            if end_key == "" and name_match(low, end_names):
                end_key = key

        free_here = free_mode or is_free_marker(node)

        if start_key != "" and end_key != "":
            start = parse_clock(node.get(start_key))
            end = parse_clock(node.get(end_key))
            if start >= 0 and end >= 0:
                if end < start:
                    end += 24 * 60
                off = direct_offset(node.get(start_key))
                if off is None:
                    off = direct_offset(node.get(end_key))
                if off is None:
                    off = current_offset
                return [start, end, off, free_here]

        if start_key != "" and "duration" in node:
            duration = parse_duration(node.get("duration"))
            if duration >= 0:
                start = parse_clock(node.get(start_key))
                if start >= 0:
                    off = direct_offset(node.get(start_key))
                    if off is None:
                        off = current_offset
                    return [start, start + duration, off, free_here]

        if end_key != "" and "duration" in node:
            duration = parse_duration(node.get("duration"))
            if duration >= 0:
                end = parse_clock(node.get(end_key))
                if end >= 0:
                    off = direct_offset(node.get(end_key))
                    if off is None:
                        off = current_offset
                    return [end - duration, end, off, free_here]

        all_day = False
        for key in ["all_day", "allday", "full_day", "fullDay", "full_day_event"]:
            if key in node:
                value = node.get(key)
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    all_day = True
        if all_day:
            return [0, 24 * 60, current_offset, free_here]

        return None

    def select_day_node(node, day):
        if type(node) != dict:
            return node

        variants = [day, day.lower(), day.upper(), day.title(), day.capitalize()]
        if len(day) >= 3:
            variants.append(day[:3].lower())
            variants.append(day[:3].upper())
            variants.append(day[:3].title())

        if day.lower() == "mon":
            variants.extend(["monday", "Monday"])
        if day.lower() == "tue":
