        if day.lower() == "wed":
            variants.extend(["wednesday", "Wednesday"])
        if day.lower() == "thu":
            variants.extend(["thursday", "Thursday", "thur", "Thur", "thurs", "Thurs"])
        if day.lower() == "fri":
            variants.extend(["friday", "Friday"])

        for key in node:
            low = str(key).lower()
            for item in variants:
                item_low = item.lower()
                if low == item_low or low.endswith(item_low):
                    return node.get(key)
        return node

    def scan(node, day, inherited_offset, before, after, free_mode, busy_holder, free_holder, user_offset):
        if type(node) == list:
            if len(node) == 2 and type(node[0]) != dict and type(node[0]) != list and type(node[1]) != dict and type(node[1]) != list:
                start = parse_clock(node[0])
