            else:
                add_interval(interval[0], interval[1], interval[2], before, after, user_offset, busy_holder, False)

        for key in node:
            value = node.get(key)
            low = str(key).lower()

            if is_note_key(low):
                continue

            child_free = current_free
            if is_free_container_key(low):
                child_free = True
            if is_busy_container_key(low):
                child_free = False

            if type(value) == dict or type(value) == list:
                scan(value, day, current_offset, before, after, child_free, busy_holder, free_holder, user_offset)
            elif type(value) == str:
                if child_free:
                    parse_range_string(value, current_offset, 0, 0, user_offset, free_holder, True)
                else:
                    parse_range_string(value, current_offset, before, after, user_offset, busy_holder, False)

    people = []
    seen = {}
    for person in [""] + attendees:
