        if ":" in s:
            parts = s.split(":")
            if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                return sign * (int(parts[0].strip()) * 60 + int(parts[1].strip()[:2]))

        total = 0
        num = ""
        found = False
        i = 0
        while i < len(s):
            ch = s[i]
            if ch.isdigit():
                num += ch
            else:
                if num:
                    tail = s[i:]
                    if tail.startswith("hour") or tail.startswith("hours") or tail.startswith("hr") or tail.startswith("hrs") or tail.startswith("h"):
                        total += int(num) * 60
                        found = True
                        num = ""
                    elif tail.startswith("minute") or tail.startswith("minutes") or tail.startswith("min") or tail.startswith("m"):
                        total += int(num)
                        found = True
                        num = ""
                    elif tail.startswith("second") or tail.startswith("seconds") or tail.startswith("sec") or tail.startswith("s"):
                        total += int(num) // 60
                        found = True
                        num = ""
            i += 1

        if num:
            if found:
                total += int(num)
            else:
                return sign * int(num)

        if found:
            return sign * total
        return -1

    def parse_clock(value):
        if type(value) == bool:
            return -1
        if type(value) == int:
            if 0 <= value <= 24:
                return value * 60
            if 0 <= value <= 24 * 60:
                return value
            return -1
        if type(value) == list:
            for item in value:
                result = parse_clock(item)
                if result >= 0:
                    return result
            return -1
        if type(value) == dict:
            keys = [
                "dateTime", "datetime", "date_time", "time", "value", "start", "end",
                "begin", "from", "to", "dtstart", "dtend", "start_time", "end_time",
                "startTime", "endTime", "starttime", "endtime", "start_date", "end_date",
                "startDate", "endDate", "open", "close", "available_from", "available_to",
                "free_from", "free_to"
            ]
            for key in keys:
                if key in value:
                    result = parse_clock(value.get(key))
                    if result >= 0:
                        return result
            for key in value:
                result = parse_clock(value.get(key))
                if result >= 0:
                    return result
            return -1
        if type(value) != str:
            return -1

        s = value.strip()
        if not s:
            return -1

        lowfull = s.lower()
        if lowfull == "noon" or lowfull == "midday":
            return 12 * 60
        if lowfull == "midnight":
            return 0

        if "T" in s:
            s = s.rsplit("T", 1)[-1].strip()

        if s.endswith("Z") or s.endswith("z"):
            s = s[:-1].strip()
        else:
            off = parse_offset_value(s)
            if off is not None:
                i = len(s) - 1
                while i >= 0:
                    ch = s[i]
                    if ch == "+" or ch == "-":
                        if i + 1 < len(s) and s[i + 1].isdigit():
                            tail = s[i:]
                            if parse_offset_value(tail) is not None:
                                s = s[:i].strip()
                                break
                    i -= 1

        cleaned = s.replace(".", " ").replace(",", " ").replace(";", " ").replace("(", " ").replace(")", " ")
        cleaned = cleaned.replace("[", " ").replace("]", " ").replace("{", " ").replace("}", " ")
        cleaned = cleaned.replace("\n", " ").replace("\t", " ").replace("|", " ")
        tokens = cleaned.split()

        for i in range(len(tokens)):
            tok = tokens[i].strip()
            if not tok:
                continue

            core = tok
            if len(core) > 1 and (core.endswith("Z") or core.endswith("z")):
                core = core[:-1]

            low = core.lower()
            if low.endswith("am") or low.endswith("pm"):
                suffix = low[-2:]
                body = core[:-2].strip()
                result = parse_clock(body)
                if result >= 0:
                    hour = result // 60
                    minute = result % 60
                    if suffix == "am":
                        if hour == 12:
                            hour = 0
                    else:
                        if hour != 12:
                            hour += 12
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if ":" in core:
                j = 1
                signpos = -1
                while j < len(core):
                    if core[j] == "+" or core[j] == "-":
                        if core[j - 1].isdigit():
                            signpos = j
                            break
                    j += 1
                if signpos >= 0:
                    core = core[:signpos]

                parts = core.split(":")
                if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                    hour = int(parts[0].strip())
                    minute = int(parts[1].strip()[:2])
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if core.isdigit():
                num = int(core)
                if 0 <= num <= 24:
                    return num * 60
                if len(core) == 3 or len(core) == 4:
                    hour = int(core[:-2])
                    minute = int(core[-2:])
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

        for i in range(len(tokens)):
            low = tokens[i].lower()
            if low in ["am", "pm"] and i > 0:
                result = parse_clock(tokens[i - 1])
                if result >= 0:
                    hour = result // 60
                    minute = result % 60
                    if low == "am":
                        if hour == 12:
                            hour = 0
                    else:
                        if hour != 12:
                            hour += 12
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute
        return -1

    def is_note_key(low):
        names = [
            "notes", "note", "description", "desc", "comment", "comments", "text",
            "body", "message", "summary", "subject", "title", "details", "memo",
            "remarks", "remark"
        ]
        for name in names:
            if low == name or low.endswith(name):
                return True
        return False

    def is_free_container_key(low):
        names = [
            "working_hours", "work_hours", "office_hours", "business_hours",
            "open_hours", "openhours", "businesshours", "free_windows",
            "free_times", "available_windows", "available_times", "availability",
            "workinghours", "officehours", "businesshours"
        ]
        return name_match(low, names)

    def is_busy_container_key(low):
        names = ["busy", "busy_times", "busy_periods", "busy_ranges", "busy_slots", "slots", "periods"]
        return name_match(low, names)

    def is_free_marker(node):
        if type(node) != dict:
            return False

        if "busy" in node:
            value = node.get("busy")
            if value is False:
                return True
            if type(value) == str:
                low = value.lower().strip()
                if low == "free" or low == "available" or low == "transparent" or low == "optional" or low == "false" or low == "no" or low == "canceled" or low == "cancelled" or low == "declined":
                    return True

        for key in ["free", "is_free", "available", "transparent", "optional"]:
            if key in node:
                value = node.get(key)
                if value is True:
                    return True
                if type(value) == str:
                    low = value.lower().strip()
                    if low == "true" or low == "yes" or low == "free" or low == "available" or low == "transparent" or low == "optional":
                        return True

        for key in ["show_as", "status", "availability", "visibility"]:
            if key in node:
                value = node.get(key)
                if type(value) == str:
                    low = value.lower().strip()
                    if low == "free" or low == "available" or low == "transparent" or low == "optional" or low == "canceled" or low == "cancelled" or low == "declined":
                        return True

        return False

    def text_buffer(text):
        before = 0
        after = 0
        if type(text) != str:
            return before, after

        s = text.lower()
        for ch in [",", ";", "(", ")", "[", "]", ".", ":", "/", "_", "\n", "\t", "|", "-", "–", "—"]:
            s = s.replace(ch, " ")
        tokens = s.split()

        before_words = ["before", "pre", "lead", "leading", "prior", "prep"]
        after_words = ["after", "post", "trailing", "trail", "following", "follow", "wrap", "lag"]
        both_words = ["buffer", "padding", "pad", "margin", "gap"]

        def token_minutes(tok):
            if tok.isdigit():
                return int(tok)
            if tok.endswith("hours") and tok[:-5].isdigit():
                return int(tok[:-5]) * 60
            if tok.endswith("hour") and tok[:-4].isdigit():
                return int(tok[:-4]) * 60
            if tok.endswith("hrs") and tok[:-3].isdigit():
                return int(tok[:-3]) * 60
            if tok.endswith("hr") and tok[:-2].isdigit():
                return int(tok[:-2]) * 60
            if tok.endswith("h") and tok[:-1].isdigit():
                return int(tok[:-1]) * 60
            if tok.endswith("minutes") and tok[:-7].isdigit():
                return int(tok[:-7])
            if tok.endswith("minute") and tok[:-6].isdigit():
                return int(tok[:-6])
            if tok.endswith("mins") and tok[:-4].isdigit():
                return int(tok[:-4])
            if tok.endswith("min") and tok[:-3].isdigit():
                return int(tok[:-3])
            if tok.endswith("m") and tok[:-1].isdigit():
                return int(tok[:-1])
            if tok.endswith("seconds") and tok[:-7].isdigit():
                return int(tok[:-7]) // 60
            if tok.endswith("second") and tok[:-6].isdigit():
                return int(tok[:-6]) // 60
            if tok.endswith("secs") and tok[:-4].isdigit():
                return int(tok[:-4]) // 60
            if tok.endswith("sec") and tok[:-3].isdigit():
                return int(tok[:-3]) // 60
            if tok.endswith("s") and tok[:-1].isdigit():
                return int(tok[:-1]) // 60
            return -1

        for i in range(len(tokens)):
            num = token_minutes(tokens[i])
            if num < 0:
                continue
            left = i - 3
            if left < 0:
                left = 0
            right = i + 4
            if right > len(tokens):
                right = len(tokens)
            window = tokens[left:right]
            has_before = False
            has_after = False
            has_both = False
            for word in window:
                if word in before_words:
                    has_before = True
                if word in after_words:
                    has_after = True
                if word in both_words:
                    has_both = True
            if has_both and not has_before and not has_after:
                if num > before:
                    before = num
                if num > after:
                    after = num
            else:
                if has_before and num > before:
                    before = num
                if has_after and num > after:
                    after = num
        return before, after

    def note_buffer(node):
        before = 0
        after = 0
        if type(node) == dict:
            for key in node:
                low = str(key).lower()
                value = node.get(key)
                if is_note_key(low):
                    tb, ta = note_buffer(value)
                    if tb > before:
                        before = tb
                    if ta > after:
                        after = ta
                elif low == "buffer" or low == "padding" or low == "gap" or low == "margin" or low == "lead_time" or low == "lag_time" or low == "leadtime" or low == "lagtime" or "buffer" in low or "padding" in low or "margin" in low or "gap" in low:
                    num = parse_duration(value)
                    if num < 0 and type(value) == str:
                        tb, ta = text_buffer(value)
                        if tb > before:
                            before = tb
                        if ta > after:
                            after = ta
                    elif num >= 0:
                        if ("after" in low) or ("lag" in low) or ("post" in low) or ("trail" in low):
                            if num > after:
                                after = num
                        elif ("before" in low) or ("pre" in low) or ("lead" in low):
                            if num > before:
                                before = num
                        else:
                            if num > before:
                                before = num
                            if num > after:
                                after = num
                elif "before" in low or "pre" in low or "lead" in low:
                    num = parse_duration(value)
                    if num < 0 and type(value) == str:
                        tb, ta = text_buffer(value)
                        if tb > before:
                            before = tb
                    elif num >= 0 and num > before:
                        before = num
                elif "after" in low or "post" in low or "trail" in low or "follow" in low or "lag" in low:
                    num = parse_duration(value)
                    if num < 0 and type(value) == str:
                        tb, ta = text_buffer(value)
                        if ta > after:
                            after = ta
                    elif num >= 0 and num > after:
                        after = num

                if (type(value) == dict or type(value) == list) and (is_note_key(low) or "buffer" in low or "padding" in low or "margin" in low or "gap" in low or "before" in low or "after" in low or "pre" in low or "post" in low or "lead" in low or "trail" in low or "lag" in low):
                    tb, ta = note_buffer(value)
                    if tb > before:
                        before = tb
                    if ta > after:
                        after = ta
        elif type(node) == list:
            for item in node:
                tb, ta = note_buffer(item)
                if tb > before:
                    before = tb
                if ta > after:
                    after = ta
        elif type(node) == str:
            tb, ta = text_buffer(node)
            if tb > before:
                before = tb
            if ta > after:
                after = ta
        return before, after

    def merge_intervals(intervals):
        items = []
        for item in intervals:
            if type(item) != list or len(item) < 2:
                continue
            start = item[0]
            end = item[1]
            if start is None or end is None:
                continue
            if end > start:
                items.append([start, end])
        items.sort()
        merged = []
        for start, end in items:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            elif end > merged[-1][1]:
                merged[-1][1] = end
        return merged

    def subtract_intervals(base, cuts):
        cuts = merge_intervals(cuts)
        result = []
        for start, end in base:
            pos = start
            for cut_start, cut_end in cuts:
                if cut_end <= pos:
                    continue
                if cut_start >= end:
                    break
                if cut_start > pos:
                    right = cut_start
                    if right > end:
                        right = end
                    if right > pos:
                        result.append([pos, right])
                if cut_end > pos:
                    pos = cut_end
                if pos >= end:
                    break
            if pos < end:
                result.append([pos, end])
        return merge_intervals(result)

    def intersect_intervals(left, right):
        left = merge_intervals(left)
        right = merge_intervals(right)
        result = []
        i = 0
        j = 0
        while i < len(left) and j < len(right):
            start = left[i][0]
            if right[j][0] > start:
                start = right[j][0]
            end = left[i][1]
            if right[j][1] < end:
                end = right[j][1]
            if start < end:
                result.append([start, end])
            if left[i][1] < right[j][1]:
                i += 1
            else:
                j += 1
        return merge_intervals(result)

    def add_interval(start, end, offset, before, after, user_offset, holder, free_mode):
        if start is None or end is None:
            return
        if end < start:
            end += 24 * 60
        if offset is None:
            offset = user_offset
        delta = user_offset - offset
        s = start + delta
        e = end + delta
        if not free_mode:
            s -= before
            e += after
        if e <= 0 or s >= 24 * 60:
            return
        if s < 0:
            s = 0
        if e > 24 * 60:
            e = 24 * 60
        if s < e:
            holder.append([s, e])

    def parse_range_string(text, current_offset, before, after, user_offset, holder, free_mode):
        if type(text) != str:
            return
        s = text.strip()
        if not s:
            return

        s = s.replace("–", "-").replace("—", "-")
        s = s.replace("\n", ";")
        parts = s.split(";")
        for part in parts:
            piece = part.strip()
            if not piece:
                continue

            candidates = []
            for token in [" - ", " to ", " until ", " through "]:
                idx = piece.find(token)
                if idx >= 0:
                    candidates.append([idx, len(token)])

            if piece.count("-") == 1:
                idx = piece.find("-")
                if idx > 0 and idx + 1 < len(piece):
                    candidates.append([idx, 1])

            made = False
            for item in candidates:
                idx = item[0]
                size = item[1]
                left = piece[:idx].strip()
                right = piece[idx + size:].strip()
                if not left or not right:
                    continue
                start = parse_clock(left)
                end = parse_clock(right)
                if start >= 0 and end >= 0:
                    off = current_offset
                    off0 = parse_offset_value(left)
                    if off0 is not None:
                        off = off0
                    off1 = parse_offset_value(right)
                    if off1 is not None:
                        off = off1
                    add_interval(start, end, off, before, after, user_offset, holder, free_mode)
                    made = True
                    break
            if made:
                continue

    def select_day_node(node, day):
        if type(node) != dict:
            return node

        variants = [day, day.lower(), day.upper(), day.title(), day.capitalize()]
        if len(day) >= 3:
            variants.append(day[:3].lower())
            variants.append(day[:3].upper())
            variants.append(day[:3].title())

        if day.lower() == "mon":
            variants.extend(["monday", "Monday"])
        if day.lower() == "tue":
            variants.extend(["tuesday", "Tuesday", "tues", "Tues"])
        if day.lower() == "wed":
            variants.extend(["wednesday", "Wednesday"])
        if day.lower() == "thu":
            variants.extend(["thursday", "Thursday", "thur", "Thur", "thurs", "Thurs"])
        if day.lower() == "fri":
            variants.extend(["friday", "Friday"])

        for key in node:
            low = str(key).lower()
            for item in variants:
                item_low = item.lower()
                if low == item_low or low.endswith(item_low):
                    return node.get(key)
        return node

    def get_interval(node, current_offset, free_mode):
        if type(node) != dict:
            return None

        start_names = [
            "start", "begin", "from", "datetime", "dateTime", "time", "dtstart",
            "start_time", "startTime", "starttime", "start_date", "startDate"
        ]
        end_names = [
            "end", "finish", "to", "dtend", "end_time", "endTime", "endtime",
            "end_date", "endDate"
        ]
        if free_mode:
            start_names = start_names + ["available_from", "free_from", "open"]
            end_names = end_names + ["available_to", "free_to", "close"]

        start_key = ""
        end_key = ""
        for key in node:
            low = str(key).lower()
            if start_key == "" and name_match(low, start_names):
                start_key = key
            if end_key == "" and name_match(low, end_names):
                end_key = key

        free_here = free_mode or is_free_marker(node)

        if start_key != "" and end_key != "":
            start_val = node.get(start_key)
            end_val = node.get(end_key)
            start = parse_clock(start_val)
            end = parse_clock(end_val)
            if start >= 0 and end >= 0:
                if end < start:
                    end += 24 * 60
                off = parse_offset_value(start_val)
                if off is None:
                    off = parse_offset_value(end_val)
                if off is None:
                    off = direct_offset(node)
                if off is None:
                    off = current_offset
                return [start, end, off, free_here]

        if start_key != "" and "duration" in node:
            duration = parse_duration(node.get("duration"))
            if duration >= 0:
                start = parse_clock(node.get(start_key))
                if start >= 0:
                    off = parse_offset_value(node.get(start_key))
                    if off is None:
                        off = direct_offset(node)
                    if off is None:
                        off = current_offset
                    return [start, start + duration, off, free_here]

        if end_key != "" and "duration" in node:
            duration = parse_duration(node.get("duration"))
            if duration >= 0:
                end = parse_clock(node.get(end_key))
                if end >= 0:
                    off = parse_offset_value(node.get(end_key))
                    if off is None:
                        off = direct_offset(node)
                    if off is None:
                        off = current_offset
                    return [end - duration, end, off, free_here]

        all_day = False
        for key in ["all_day", "allday", "full_day", "fullDay", "full_day_event"]:
            if key in node:
                value = node.get(key)
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    all_day = True
        if all_day:
            return [0, 24 * 60, current_offset, free_here]

        return None

    def scan(node, day, inherited_offset, before, after, free_mode, busy_holder, free_holder, user_offset):
        if type(node) == list:
            if len(node) == 2 and type(node[0]) != dict and type(node[0]) != list and type(node[1]) != dict and type(node[1]) != list:
                start = parse_clock(node[0])
                end = parse_clock(node[1])
                if start >= 0 and end >= 0:
                    if end < start:
                        end += 24 * 60
                    off = parse_offset_value(node[0])
                    if off is None:
                        off = parse_offset_value(node[1])
                    if off is None:
                        off = inherited_offset
                    if free_mode:
                        add_interval(start, end, off, 0, 0, user_offset, free_holder, True)
                    else:
                        add_interval(start, end, off, before, after, user_offset, busy_holder, False)
                    return
            for item in node:
                scan(item, day, inherited_offset, before, after, free_mode, busy_holder, free_holder, user_offset)
            return

        if type(node) != dict:
            if type(node) == str:
                if free_mode:
                    parse_range_string(node, inherited_offset, 0, 0, user_offset, free_holder, True)
                else:
                    parse_range_string(node, inherited_offset, before, after, user_offset, busy_holder, False)
            return

        current_offset = direct_offset(node)
        if current_offset is None:
            current_offset = inherited_offset

        local_before, local_after = note_buffer(node)
        if local_before > before:
            before = local_before
        if local_after > after:
            after = local_after

        picked = select_day_node(node, day)
        if picked is not node:
            scan(picked, day, current_offset, before, after, free_mode, busy_holder, free_holder, user_offset)
            return

        current_free = free_mode or is_free_marker(node)

        if len(node) == 1:
            for key in node:
                low = str(key).lower()
                if is_free_container_key(low):
                    current_free = True
                if is_busy_container_key(low):
                    current_free = False

        interval = get_interval(node, current_offset, current_free)
        if interval is not None:
            if interval[3]:
                add_interval(interval[0], interval[1], interval[2], 0, 0, user_offset, free_holder, True)
            else:
                add_interval(interval[0], interval[1], interval[2], before, after, user_offset, busy_holder, False)

        for key in node:
            value = node.get(key)
            low = str(key).lower()

            if is_note_key(low):
                continue

            child_free = current_free
            if is_free_container_key(low):
                child_free = True
            if is_busy_container_key(low):
                child_free = False

            if type(value) == dict or type(value) == list:
                scan(value, day, current_offset, before, after, child_free, busy_holder, free_holder, user_offset)
            elif type(value) == str:
                if child_free:
                    parse_range_string(value, current_offset, 0, 0, user_offset, free_holder, True)
                else:
                    parse_range_string(value, current_offset, before, after, user_offset, busy_holder, False)

    people = []
    seen = {}
    for person in [""] + attendees:
        if person not in seen:
            seen[person] = 1
            people.append(person)

    result = {"starts": {}}

    if minutes <= 0 or not days:
        return result

    earliest_minutes = 0
    latest_minutes = 24 * 60
    if earliest:
        temp = parse_clock(earliest)
        if temp >= 0:
            earliest_minutes = temp
    if latest_end:
        temp = parse_clock(latest_end)
        if temp >= 0:
            latest_minutes = temp
