        if not s:
            return -1

        sign = 1
        if s[0] == "+":
            s = s[1:].strip()
        elif s[0] == "-":
            sign = -1
            s = s[1:].strip()
        if not s:
            return -1

        if s.startswith("pt"):
            s = s[2:]

        if ":" in s:
            parts = s.split(":")
            if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                return sign * (int(parts[0].strip()) * 60 + int(parts[1].strip()[:2]))

        total = 0
        num = ""
        found = False
        i = 0
        while i < len(s):
            ch = s[i]
            if ch.isdigit():
                num += ch
            else:
                if num:
                    tail = s[i:]
                    if tail.startswith("hour") or tail.startswith("hours") or tail.startswith("hr") or tail.startswith("hrs") or tail.startswith("h"):
                        total += int(num) * 60
                        found = True
                        num = ""
                    elif tail.startswith("minute") or tail.startswith("minutes") or tail.startswith("min") or tail.startswith("m"):
                        total += int(num)
                        found = True
                        num = ""
                    elif tail.startswith("second") or tail.startswith("seconds") or tail.startswith("sec") or tail.startswith("secs") or tail.startswith("s"):
                        total += int(num) // 60
                        found = True
                        num = ""
            i += 1

        if num:
            if found:
                total += int(num)
            else:
                return sign * int(num)

        if found:
            return sign * total
        return -1

    def parseClock(value):
        if type(value) == bool:
            return -1
        if type(value) == int:
            if 0 <= value <= 24:
                return value * 60
            if 0 <= value <= 24 * 60:
                return value
            return -1
        if type(value) == list:
            for item in value:
                result = parseClock(item)
                if result >= 0:
                    return result
            return -1
        if type(value) == dict:
            keys = [
                "dateTime", "datetime", "date_time", "time", "value", "start", "end",
                "begin", "from", "to", "dtstart", "dtend", "start_time", "end_time",
                "startTime", "endTime", "starttime", "endtime", "start_date", "end_date",
                "startDate", "endDate", "open", "close", "available_from", "available_to",
                "free_from", "free_to"
            ]
            for key in keys:
                if key in value:
                    result = parseClock(value.get(key))
                    if result >= 0:
                        return result
            for key in value:
                result = parseClock(value.get(key))
                if result >= 0:
                    return result
            return -1
        if type(value) != str:
            return -1

        s = value.strip()
        if not s:
            return -1

        lowfull = s.lower()
        if lowfull == "noon" or lowfull == "midday":
            return 12 * 60
        if lowfull == "midnight":
            return 0

        if "T" in s:
            s = s.rsplit("T", 1)[-1].strip()

        cleaned = s.replace(".", " ").replace(",", " ").replace(";", " ").replace("(", " ").replace(")", " ")
        cleaned = cleaned.replace("[", " ").replace("]", " ").replace("{", " ").replace("}", " ")
        cleaned = cleaned.replace("\n", " ").replace("\t", " ").replace("|", " ").replace("/", " ")
        tokens = cleaned.split()

        for i in range(len(tokens)):
            tok = tokens[i].strip()
            if not tok:
                continue

            core = tok
            if len(core) > 1 and (core.endswith("Z") or core.endswith("z")):
                core = core[:-1]

            low = core.lower()
            if low.endswith("am") or low.endswith("pm"):
                suffix = low[-2:]
                body = core[:-2].strip()
                result = parseClock(body)
                if result >= 0:
                    hour = result // 60
                    minute = result % 60
                    if suffix == "am":
                        if hour == 12:
                            hour = 0
                    else:
                        if hour != 12:
                            hour += 12
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if ":" in core:
                j = 1
                signpos = -1
                while j < len(core):
                    if core[j] == "+" or core[j] == "-":
                        if core[j - 1].isdigit():
                            signpos = j
                            break
                    j += 1
                if signpos >= 0 and ("T" in value or " " in value):
                    core = core[:signpos]

                parts = core.split(":")
                if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                    hour = int(parts[0].strip())
                    minute = int(parts[1].strip()[:2])
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

            if core.isdigit():
                num = int(core)
                if 0 <= num <= 24:
                    return num * 60
                if len(core) == 3 or len(core) == 4:
                    hour = int(core[:-2])
                    minute = int(core[-2:])
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute

        for i in range(len(tokens)):
            low = tokens[i].lower()
            if low in ["am", "pm"] and i > 0:
                result = parseClock(tokens[i - 1])
                if result >= 0:
                    hour = result // 60
                    minute = result % 60
                    if low == "am":
                        if hour == 12:
                            hour = 0
                    else:
                        if hour != 12:
                            hour += 12
                    if hour == 24 and minute == 0:
                        return 1440
                    if 0 <= hour <= 23 and 0 <= minute <= 59:
                        return hour * 60 + minute
        return -1

