    def textBuffer(text):
        before = 0
        after = 0
        if type(text) != str:
            return before, after

        s = text.lower()
        for ch in [",", ";", "(", ")", "[", "]", ".", ":", "/", "_", "\n", "\t", "|", "-", "–", "—"]:
            s = s.replace(ch, " ")
        tokens = s.split()

        beforeWords = ["before", "pre", "lead", "leading", "prior", "prep"]
        afterWords = ["after", "post", "trailing", "trail", "following", "follow", "wrap", "lag"]
        bothWords = ["buffer", "padding", "pad", "margin", "gap"]

        def tokenMinutes(tok):
            if tok.isdigit():
                return int(tok)
            if tok.endswith("hours") and tok[:-5].isdigit():
                return int(tok[:-5]) * 60
            if tok.endswith("hour") and tok[:-4].isdigit():
                return int(tok[:-4]) * 60
            if tok.endswith("hrs") and tok[:-3].isdigit():
                return int(tok[:-3]) * 60
            if tok.endswith("hr") and tok[:-2].isdigit():
                return int(tok[:-2]) * 60
            if tok.endswith("h") and tok[:-1].isdigit():
                return int(tok[:-1]) * 60
            if tok.endswith("minutes") and tok[:-7].isdigit():
                return int(tok[:-7])
            if tok.endswith("minute") and tok[:-6].isdigit():
                return int(tok[:-6])
            if tok.endswith("mins") and tok[:-4].isdigit():
                return int(tok[:-4])
            if tok.endswith("min") and tok[:-3].isdigit():
                return int(tok[:-3])
            if tok.endswith("m") and tok[:-1].isdigit():
                return int(tok[:-1])
            if tok.endswith("seconds") and tok[:-7].isdigit():
                return int(tok[:-7]) // 60
            if tok.endswith("second") and tok[:-6].isdigit():
                return int(tok[:-6]) // 60
            if tok.endswith("secs") and tok[:-4].isdigit():
                return int(tok[:-4]) // 60
            if tok.endswith("sec") and tok[:-3].isdigit():
                return int(tok[:-3]) // 60
            if tok.endswith("s") and tok[:-1].isdigit():
                return int(tok[:-1]) // 60
            return -1

        for i in range(len(tokens)):
            num = tokenMinutes(tokens[i])
            if num < 0:
                continue
            left = i - 3
            if left < 0:
                left = 0
            right = i + 4
            if right > len(tokens):
                right = len(tokens)
            window = tokens[left:right]
            hasBefore = False
            hasAfter = False
            hasBoth = False
            for word in window:
                if word in beforeWords:
                    hasBefore = True
                if word in afterWords:
                    hasAfter = True
                if word in bothWords:
                    hasBoth = True
            if hasBoth and not hasBefore and not hasAfter:
                if num > before:
                    before = num
                if num > after:
                    after = num
            else:
                if hasBefore and num > before:
                    before = num
                if hasAfter and num > after:
                    after = num
        return before, after

    def noteBuffer(node):
