                if (type(value) == dict or type(value) == list) and (isNoteKey(low) or "buffer" in low or "padding" in low or "margin" in low or "gap" in low or "before" in low or "after" in low or "pre" in low or "post" in low or "lead" in low or "trail" in low or "lag" in low):
