        return before, after

    def mergeIntervals(intervals):
        items = []
        for item in intervals:
            if type(item) != list or len(item) < 2:
                continue
            start = item[0]
            end = item[1]
            if start is None or end is None:
                continue
            if end > start:
                items.append([start, end])
        items.sort()
        merged = []
        for start, end in items:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            elif end > merged[-1][1]:
                merged[-1][1] = end
        return merged

    def subtractIntervals(base, cuts):
        cuts = mergeIntervals(cuts)
        result = []
        for start, end in base:
            pos = start
            for cutStart, cutEnd in cuts:
                if cutEnd <= pos:
                    continue
                if cutStart >= end:
                    break
                if cutStart > pos:
                    right = cutStart
                    if right > end:
                        right = end
                    if right > pos:
                        result.append([pos, right])
                if cutEnd > pos:
                    pos = cutEnd
                if pos >= end:
                    break
            if pos < end:
                result.append([pos, end])
        return mergeIntervals(result)

    def intersectIntervals(left, right):
        left = mergeIntervals(left)
        right = mergeIntervals(right)
        result = []
        i = 0
        j = 0
        while i < len(left) and j < len(right):
            start = left[i][0]
            if right[j][0] > start:
                start = right[j][0]
            end = left[i][1]
            if right[j][1] < end:
                end = right[j][1]
            if start < end:
                result.append([start, end])
            if left[i][1] < right[j][1]:
                i += 1
            else:
                j += 1
        return mergeIntervals(result)

    def addInterval(start, end, offset, before, after, userOffset, holder, freeMode):
        if start is None or end is None:
            return
        if end < start:
            end += 24 * 60
        if offset is None:
            offset = userOffset
        delta = userOffset - offset
        s = start + delta
        e = end + delta
        if not freeMode:
            s -= before
            e += after
        if e <= 0 or s >= 24 * 60:
            return
        if s < 0:
            s = 0
        if e > 24 * 60:
            e = 24 * 60
        if s < e:
            holder.append([s, e])

    def parseRangeString(text, currentOffset, before, after, userOffset, holder, freeMode):
        if type(text) != str:
            return
        s = text.strip()
        if not s:
            return

        s = s.replace("–", "-").replace("—", "-")
        s = s.replace("\n", ";").replace(",", ";")
        parts = s.split(";")
        for part in parts:
            piece = part.strip()
            if not piece:
                continue

            idx = -1
            size = 0
            for token in [" to ", " until ", " through "]:
                temp = piece.find(token)
                if temp >= 0:
                    idx = temp
                    size = len(token)
                    break

            if idx < 0:
                temp = piece.find(" - ")
                if temp >= 0:
                    idx = temp
                    size = 3
                else:
                    if piece.count("-") == 1:
                        idx = piece.find("-")
                        size = 1

            if idx < 0:
                continue

            left = piece[:idx].strip()
            right = piece[idx + size:].strip()
            if not left or not right:
                continue

            start = parseClock(left)
            end = parseClock(right)
            if start >= 0 and end >= 0:
                off = currentOffset
                off0 = parseOffset(left)
                if off0 is not None:
                    off = off0
                off1 = parseOffset(right)
                if off1 is not None:
                    off = off1
                addInterval(start, end, off, before, after, userOffset, holder, freeMode)

