                    if off is None:
                        off = currentOffset
                    return [start, start + duration, off, freeHere]

        if endKey != "" and "duration" in node:
            duration = parseDuration(node.get("duration"))
            if duration >= 0:
                end = parseClock(node.get(endKey))
                if end >= 0:
                    off = parseOffset(node.get(endKey))
                    if off is None:
                        off = directOffset(node)
                    if off is None:
                        off = currentOffset
                    return [end - duration, end, off, freeHere]

        allDay = False
        for key in ["all_day", "allday", "full_day", "fullDay", "full_day_event"]:
