                        off = parseOffset(node[1])
                    if off is None:
                        off = inheritedOffset
                    if mode == "free":
                        addInterval(start, end, off, 0, 0, userOffset, freeHolder, True)
                    else:
                        addInterval(start, end, off, before, after, userOffset, busyHolder, False)
