            return
        if end < start:
            end += 24 * 60
        if offset is None:
            offset = userOffset
        delta = userOffset - offset
        s = start + delta
        e = end + delta
        if not freeMode:
            s -= before
            e += after
        if e <= 0 or s >= 24 * 60:
            return
        if s < 0:
            s = 0
        if e > 24 * 60:
            e = 24 * 60
        if s < e:
            holder.append([s, e])

    def parseRangeString(text, currentOffset, before, after, userOffset, holder, freeMode):
        if type(text) != str:
            return
        s = text.strip()
        if not s:
            return

        s = s.replace("–", "-").replace("—", "-")
        s = s.replace("\n", ";").replace(",", ";")
        parts = s.split(";")
        for part in parts:
            piece = part.strip()
            if not piece:
                continue

            idx = -1
            size = 0
            for token in [" to ", " until ", " through "]:
                temp = piece.find(token)
                if temp >= 0:
                    idx = temp
                    size = len(token)
                    break

            if idx < 0:
                temp = piece.find(" - ")
                if temp >= 0:
                    idx = temp
                    size = 3
                else:
                    if piece.count("-") == 1:
                        idx = piece.find("-")
                        size = 1

            if idx < 0:
                continue

            left = piece[:idx].strip()
            right = piece[idx + size:].strip()
            if not left or not right:
                continue

            start = parseClock(left)
            end = parseClock(right)
            if start >= 0 and end >= 0:
                off = currentOffset
                off0 = parseOffset(left)
                if off0 is not None:
                    off = off0
                off1 = parseOffset(right)
                if off1 is not None:
                    off = off1
                addInterval(start, end, off, before, after, userOffset, holder, freeMode)

    def selectDayNode(node, day):
        if type(node) != dict:
            return node

        variants = dayVariants(day)
        for key in node:
            low = str(key).lower()
            for item in variants:
                itemLow = item.lower()
                if low == itemLow or low.endswith(itemLow):
                    return node.get(key)
        return node

    def getInterval(node, currentOffset, freeMode):
        if type(node) != dict:
            return None

        startNames = [
            "start", "begin", "from", "datetime", "dateTime", "time", "dtstart",
            "start_time", "startTime", "starttime", "start_date", "startDate",
            "available_from", "free_from", "open", "available_start", "free_start"
        ]
        endNames = [
            "end", "finish", "to", "dtend", "end_time", "endTime", "endtime",
            "end_date", "endDate", "available_to", "free_to", "close",
            "available_end", "free_end"
        ]

        startKey = ""
        endKey = ""
        for key in node:
            low = str(key).lower()
            if startKey == "" and matchName(low, startNames):
                startKey = key
            if endKey == "" and matchName(low, endNames):
                endKey = key

        freeHere = freeMode or isFreeMarker(node)

        if startKey != "" and endKey != "":
            startVal = node.get(startKey)
            endVal = node.get(endKey)
            start = parseClock(startVal)
            end = parseClock(endVal)
            if start >= 0 and end >= 0:
                if end < start:
                    end += 24 * 60
                off = parseOffset(startVal)
                if off is None:
                    off = parseOffset(endVal)
                if off is None:
                    off = directOffset(node)
                if off is None:
                    off = currentOffset
                return [start, end, off, freeHere]

        if startKey != "" and "duration" in node:
            duration = parseDuration(node.get("duration"))
            if duration >= 0:
                start = parseClock(node.get(startKey))
                if start >= 0:
                    off = parseOffset(node.get(startKey))
                    if off is None:
                        off = directOffset(node)
                    if off is None:
                        off = currentOffset
                    return [start, start + duration, off, freeHere]

        if endKey != "" and "duration" in node:
            duration = parseDuration(node.get("duration"))
            if duration >= 0:
                end = parseClock(node.get(endKey))
                if end >= 0:
                    off = parseOffset(node.get(endKey))
                    if off is None:
                        off = directOffset(node)
                    if off is None:
                        off = currentOffset
                    return [end - duration, end, off, freeHere]

        allDay = False
        for key in ["all_day", "allday", "full_day", "fullDay", "full_day_event"]:
            if key in node:
                value = node.get(key)
                if value is True or (type(value) == str and value.strip().lower() in ["true", "yes", "1"]):
                    allDay = True
        if allDay:
            return [0, 24 * 60, currentOffset, freeHere]

        return None

    def scan(node, day, inheritedOffset, before, after, mode, busyHolder, freeHolder, userOffset):
        if type(node) == list:
            if len(node) == 2 and type(node[0]) != dict and type(node[0]) != list and type(node[1]) != dict and type(node[1]) != list:
                start = parseClock(node[0])
                end = parseClock(node[1])
                if start >= 0 and end >= 0:
                    if end < start:
                        end += 24 * 60
                    off = parseOffset(node[0])
                    if off is None:
                        off = parseOffset(node[1])
                    if off is None:
                        off = inheritedOffset
                    if mode == "free":
                        addInterval(start, end, off, 0, 0, userOffset, freeHolder, True)
                    else:
                        addInterval(start, end, off, before, after, userOffset, busyHolder, False)
                    return
            for item in node:
                scan(item, day, inheritedOffset, before, after, mode, busyHolder, freeHolder, userOffset)
            return

        if type(node) != dict:
            if type(node) == str:
                if mode == "free":
                    parseRangeString(node, inheritedOffset, 0, 0, userOffset, freeHolder, True)
                else:
                    parseRangeString(node, inheritedOffset, before, after, userOffset, busyHolder, False)
            return

        currentOffset = directOffset(node)
        if currentOffset is None:
            currentOffset = inheritedOffset

        localBefore, localAfter = noteBuffer(node)
        if localBefore > before:
            before = localBefore
        if localAfter > after:
            after = localAfter

        picked = selectDayNode(node, day)
        if picked is not node:
            scan(picked, day, currentOffset, before, after, mode, busyHolder, freeHolder, userOffset)
            for key in node:
                low = str(key).lower()
                if dayKeyMatch(low, day):
                    continue
                if isDayKey(low):
                    continue
                if isNoteKey(low):
                    continue
                value = node.get(key)
                childMode = mode
                if isFreeContainerKey(low):
                    childMode = "free"
                if isBusyContainerKey(low):
                    childMode = "busy"
                if type(value) == dict or type(value) == list:
                    scan(value, day, currentOffset, before, after, childMode, busyHolder, freeHolder, userOffset)
                elif type(value) == str:
                    if childMode == "free":
                        parseRangeString(value, currentOffset, 0, 0, userOffset, freeHolder, True)
                    else:
                        parseRangeString(value, currentOffset, before, after, userOffset, busyHolder, False)
            return

        currentMode = mode
        if isFreeMarker(node):
            currentMode = "free"

        if len(node) == 1:
            for key in node:
                low = str(key).lower()
                if isFreeContainerKey(low):
                    currentMode = "free"
                if isBusyContainerKey(low):
                    currentMode = "busy"

        interval = getInterval(node, currentOffset, currentMode == "free")
        if interval is not None:
            if interval[3]:
                addInterval(interval[0], interval[1], interval[2], 0, 0, userOffset, freeHolder, True)
            else:
                addInterval(interval[0], interval[1], interval[2], before, after, userOffset, busyHolder, False)

        for key in node:
            value = node.get(key)
            low = str(key).lower()

            if isNoteKey(low):
                continue

            childMode = currentMode
            if isFreeContainerKey(low):
                childMode = "free"
            if isBusyContainerKey(low):
                childMode = "busy"

            if type(value) == dict or type(value) == list:
                scan(value, day, currentOffset, before, after, childMode, busyHolder, freeHolder, userOffset)
            elif type(value) == str:
                if childMode == "free":
                    parseRangeString(value, currentOffset, 0, 0, userOffset, freeHolder, True)
                else:
                    parseRangeString(value, currentOffset, before, after, userOffset, busyHolder, False)

    result = {"starts": {}}

    if minutes <= 0 or not days:
        return result

    earliestMinutes = 0
    latestMinutes = 24 * 60
    if earliest:
        temp = parseClock(earliest)
        if temp >= 0:
            earliestMinutes = temp
    if latest_end:
        temp = parseClock(latest_end)
        if temp >= 0:
            latestMinutes = temp
    if latestMinutes < earliestMinutes:
        return result

    people = []
    seen = {}
    for person in [""] + attendees:
        if person not in seen:
            seen[person] = 1
            people.append(person)

    userOffset = 0
    try:
        userCal = api.read_calendar("", days[0])
    except:
        userCal = {}
    off = directOffset(userCal)
    if off is not None:
        userOffset = off
    else:
        for day in days:
            try:
                userCal = api.read_calendar("", day)
            except:
                userCal = {}
            off = directOffset(userCal)
            if off is not None:
                userOffset = off
                break

    for day in days:
        sharedAvailable = None
        for person in people:
            try:
                cal = api.read_calendar(person, day)
            except:
                cal = {}
            if type(cal) != dict and type(cal) != list:
                cal = {}

            calendarOffset = directOffset(cal)
            if calendarOffset is None:
                calendarOffset = userOffset

            globalBefore = 0
            globalAfter = 0
            if type(cal) == dict:
                globalBefore, globalAfter = noteBuffer(cal)

            busyIntervals = []
            freeIntervals = []
            scan(cal, day, calendarOffset, globalBefore, globalAfter, "busy", busyIntervals, freeIntervals, userOffset)

            busyIntervals = mergeIntervals(busyIntervals)
            freeIntervals = mergeIntervals(freeIntervals)

            if freeIntervals:
                personAvailable = subtractIntervals(freeIntervals, busyIntervals)
            else:
                personAvailable = subtractIntervals([[0, 24 * 60]], busyIntervals)

            if sharedAvailable is None:
                sharedAvailable = personAvailable
            else:
                sharedAvailable = intersectIntervals(sharedAvailable, personAvailable)

        if sharedAvailable is None:
            sharedAvailable = [[0, 24 * 60]]

        sharedAvailable = mergeIntervals(sharedAvailable)

        dayStarts = []
        seenStarts = {}
        for start, end in sharedAvailable:
            if end <= earliestMinutes or start >= latestMinutes:
                continue
            startLimit = start
            if startLimit < earliestMinutes:
                startLimit = earliestMinutes
            endLimit = end
            if endLimit > latestMinutes:
                endLimit = latestMinutes
            if endLimit - startLimit < minutes:
                continue
            firstStart = startLimit
            if firstStart % 15 != 0:
                firstStart += 15 - (firstStart % 15)
            lastStart = endLimit - minutes
            while firstStart <= lastStart:
                if firstStart not in seenStarts:
                    seenStarts[firstStart] = 1
                    dayStarts.append(str(firstStart // 60).zfill(2) + ":" + str(firstStart % 60).zfill(2))
                firstStart += 15

        if dayStarts:
            result["starts"][day] = dayStarts

    return result
