def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def daykey(text):
        return text[:3].lower()

    def timeminutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def timefromminutes(value):
        value = value % 1440
        hours = value // 60
        mins = value % 60
        return str(hours).rjust(2, "0") + ":" + str(mins).rjust(2, "0")

    def offsetminutes(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def hoursrange(text):
        pieces = text.split("-")
        return timeminutes(pieces[0]), timeminutes(pieces[1])

    def converttouser(local_minutes, person_offset, user_offset):
        return local_minutes + user_offset - person_offset

    def mergeintervals(intervals):
        if len(intervals) == 0:
            return []
        intervals = intervals[:]
        intervals.sort()
        merged = [intervals[0][:]]
        for start, end in intervals[1:]:
            last = merged[-1]
            if start <= last[1]:
                if end > last[1]:
                    last[1] = end
            else:
                merged.append([start, end])
        return merged

    def overlaps(a_start, a_end, b_start, b_end):
        return a_start < b_end and b_start < a_end

    def read_day(person, day_text, wanted_day):
        info = api.read_calendar(person, day_text)
        person_offset = offsetminutes(info["utc_offset"])
        work_start_local, work_end_local = hoursrange(info["working_hours"])
        work_start_user = converttouser(work_start_local, person_offset, user_offset)
        work_end_user = converttouser(work_end_local, person_offset, user_offset)
        note_text = info.get("note", "")
        buffer_minutes = 15 if "leave 15 minutes free before and after" in note_text.lower() else 0

        events = []
        for item in info.get("days", []):
            if daykey(item.get("day", "")) == wanted_day:
                events = item.get("events", [])
                break

        busy = []
        for event in events:
            if event.get("show_as", "") == "busy":
                start_user = converttouser(timeminutes(event["start"]), person_offset, user_offset)
                end_user = converttouser(timeminutes(event["end"]), person_offset, user_offset)
                busy.append([start_user, end_user])

        busy = mergeintervals(busy)
        return work_start_user, work_end_user, buffer_minutes, busy

    user_info = api.read_calendar("", "")
    user_offset = offsetminutes(user_info["utc_offset"])
    user_work_start, user_work_end = hoursrange(user_info["working_hours"])
    user_work_start = converttouser(user_work_start, user_offset, user_offset)
    user_work_end = converttouser(user_work_end, user_offset, user_offset)

    earliest_minutes = timeminutes(earliest) if earliest else user_work_start
    latest_minutes = timeminutes(latest_end) if latest_end else user_work_end

    people = [""]
    for name in attendees:
        if name not in people:
            people.append(name)

    day_order = []
    seen_days = []
    for day_text in days:
        wanted = daykey(day_text)
        if wanted not in seen_days:
            seen_days.append(wanted)
            day_order.append((wanted, day_text))

    result = {"starts": {}}

    for wanted_day, day_text in day_order:
        person_data = []
        allowed_start = earliest_minutes
        allowed_end = latest_minutes

        for person in people:
            work_start_user, work_end_user, buffer_minutes, busy = read_day(person, day_text, wanted_day)
            person_data.append((buffer_minutes, busy))
            if work_start_user + buffer_minutes > allowed_start:
                allowed_start = work_start_user + buffer_minutes
            if work_end_user - buffer_minutes < allowed_end:
                allowed_end = work_end_user - buffer_minutes

        start = ((allowed_start + 14) // 15) * 15
        last_start = allowed_end - minutes
        starts = []

        while start <= last_start:
            end = start + minutes
            ok = 1
            for buffer_minutes, busy in person_data:
                check_start = start - buffer_minutes
                check_end = end + buffer_minutes
                for busy_start, busy_end in busy:
                    if overlaps(check_start, check_end, busy_start, busy_end):
                        ok = 0
                        break
                if ok == 0:
                    break
            if ok == 1:
                starts.append(timefromminutes(start))
            start += 15

        if len(starts) > 0:
            result["starts"][wanted_day] = starts

    return result
