def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def normalizeDay(day):
        x = day.strip().lower()
        if x.startswith("mon"):
            return "mon"
        if x.startswith("tue"):
            return "tue"
        if x.startswith("wed"):
            return "wed"
        if x.startswith("thu"):
            return "thu"
        if x.startswith("fri"):
            return "fri"
        return ""

    def parseTime(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def formatTime(total):
        hour = total // 60
        minute = total % 60
        return str(hour).zfill(2) + ":" + str(minute).zfill(2)

    def parseOffset(text):
        sign = 1
        if text and text[0] == "-":
            sign = -1
        hour = int(text[1:3])
        minute = int(text[4:6])
        return sign * (hour * 60 + minute)

    def ceilQuarter(total):
        return ((total + 14) // 15) * 15

    def dayMap(data):
        result = {}
        for item in data.get("days", []):
            key = normalizeDay(item.get("day", ""))
            if key:
                result[key] = item
        return result

    def parseWorking(text):
        parts = text.split("-")
        return parseTime(parts[0]), parseTime(parts[1])

    userData = api.read_calendar("", "")
    userName = userData.get("person", "")
    userOffset = parseOffset(userData.get("utc_offset", "+00:00"))
    userWorkStart, userWorkEnd = parseWorking(userData.get("working_hours", "00:00-23:59"))
    userDays = dayMap(userData)

    people = []
    people.append((userOffset, userWorkStart, userWorkEnd, userDays))

    seenPeople = {userName: 1}
    seenPeople[""] = 1
    for person in attendees:
        if person in seenPeople:
            continue
        seenPeople[person] = 1
        data = api.read_calendar(person, "")
        offset = parseOffset(data.get("utc_offset", "+00:00"))
        workStart, workEnd = parseWorking(data.get("working_hours", "00:00-23:59"))
        people.append((offset, workStart, workEnd, dayMap(data)))

    orderedDays = []
    seenDays = {}
    for day in days:
        key = normalizeDay(day)
        if key and key not in seenDays:
            seenDays[key] = 1
            orderedDays.append(key)

    earliestStart = parseTime(earliest) if earliest else 0
    latestLimit = parseTime(latest_end) if latest_end else 24 * 60

    resultDays = {}
    for dayKey in orderedDays:
        lower = ceilQuarter(earliestStart)
        if lower < ceilQuarter(userWorkStart):
            lower = ceilQuarter(userWorkStart)

        upper = 24 * 60 - minutes
        if userWorkEnd - minutes < upper:
            upper = userWorkEnd - minutes
        if latestLimit - minutes < upper:
            upper = latestLimit - minutes

        starts = []
        start = lower
        while start <= upper:
            end = start + minutes
            ok = True
            for offset, workStart, workEnd, daysMap in people:
                localStart = start + (offset - userOffset)
                localEnd = end + (offset - userOffset)

                if localStart < workStart or localEnd > workEnd:
                    ok = False
                    break

                dayInfo = daysMap.get(dayKey, {})
                for event in dayInfo.get("events", []):
                    if event.get("show_as") == "busy":
                        eventStart = parseTime(event["start"])
                        eventEnd = parseTime(event["end"])
                        if localStart < eventEnd and localEnd > eventStart:
                            ok = False
                            break
                if not ok:
                    break

            if ok:
                starts.append(formatTime(start))
            start += 15

        if starts:
            resultDays[dayKey] = starts

    return {"starts": resultDays}
